    public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged e)
    {
        activityWatcher.onGrandExchange(client.getTickCount());
    }

    /** Wilderness (varbit 5963) or a PvP / Deadman world: nothing from the backpack watcher counts there. */
    private boolean inPvp()
    {
        if (client.getVarbitValue(5963) == 1) return true;
        for (Object w : client.getWorldType())
        {
            String n = String.valueOf(w);
            if (n.contains("PVP") || n.contains("DEADMAN")) return true;
        }
        return false;
    }

    /** Sends a pet event with every item id of that pet (any variant a task lists matches), or tells the player. */
    private void reportPet(PetDetector.Drop drop)
    {
        if (!config.sendPets()) return;
        if (!drop.identified())
        {
            notice((drop.duplicate ? "Duplicate pet" : "Pet") + " received, but the plugin could not tell which one: submit it on the website.", true);
            return;
        }
        GameEvent ev = base(GameEvent.PET);
        for (int id : drop.pet.itemIds) ev.addItem(id, 1);
        ev.sourceName = drop.pet.name + (drop.duplicate ? " (duplicate)" : "");
        log.debug("pet {} identified via {}", drop.pet.name, drop.via);
        submit(ev, true);
    }

    @Subscribe
    public void onStatChanged(StatChanged e)
    {
        Skill skill = e.getSkill();
        int level = e.getLevel();
        if (skill == Skill.OVERALL) return;
        Integer previous = levels.put(skill, level);
        if (previous == null || level <= previous || !config.sendLevels()) return;
        GameEvent ev = base(GameEvent.LEVEL);
        ev.skill = skill.getName().toLowerCase(Locale.ROOT);
        ev.level = level;
        submit(ev, false);
        int total = client.getTotalLevel();
        if (total > 0)
        {
            GameEvent overall = base(GameEvent.LEVEL);
            overall.skill = "overall";
            overall.level = total;
            submit(overall, false);
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged e)
    {
        // logging out or hopping closes the board (map LOADING does not; the input ignores clicks until LOGGED_IN)
        if (e.getGameState() == GameState.LOGIN_SCREEN || e.getGameState() == GameState.HOPPING || e.getGameState() == GameState.CONNECTION_LOST) boardOverlay.close();
        if (e.getGameState() == GameState.LOGIN_SCREEN || e.getGameState() == GameState.HOPPING) requestWomUpdate();
        if (e.getGameState() == GameState.LOGGED_IN)
        {
            helloPending = true; // another account may have logged in: verify again
            helloNotBefore = 0;
        }
        if (e.getGameState() == GameState.LOGIN_SCREEN)
        {
            levels.clear(); // first StatChanged per skill after login is a baseline, not a level-up
            petDetector.reset();
            lastInventory = null;
        }
    }

    @Subscribe
    public void onGameTick(GameTick e)
    {
        int tick = client.getTickCount();
        maybeHello();
        if (petDetector.wantsFollower())
        {
            NPC follower = client.getFollower();
            if (follower != null)
            {
                petDetector.onFollower(follower.getId(), tick).ifPresent(this::reportPet);
            }
        }
        petDetector.onTick(tick).ifPresent(this::reportPet);
        // one event (and one screenshot) per activity per tick: a chest or shop trip with several uniques counts each
        Map<String, GameEvent> byActivity = new java.util.LinkedHashMap<>();
        for (ActivityWatcher.Drop d : activityWatcher.flush(tick, inPvp()))
        {
            if (!config.sendChestLoot()) continue;
            GameEvent ev = byActivity.computeIfAbsent(d.activity, k -> {
                GameEvent n = base(GameEvent.RAID_CHEST);
                n.sourceName = k; // the server knows every activity name (npc_sources aliases)
                return n;
            });
            ev.addItem(d.itemId, d.quantity);
        }
        for (GameEvent ev : byActivity.values()) submit(ev, true);
    }

    /**
     * Collection log lines carry the item name only. Pets, the board's own items and the server catalogue are
     * resolved by name (core/ItemNames); {@code ItemManager.search} only knows tradeables and is a last resort.
     */
    private Integer resolveItemId(String name)
    {
        java.util.Optional<Integer> known = itemNames.resolve(name);
        if (known.isPresent())
        {
            return known.get();
        }
        for (var price : itemManager.search(name))
        {
            if (price.getName().equalsIgnoreCase(name))
            {
                return itemManager.canonicalize(price.getId());
            }
        }
        log.debug("could not resolve collection log item '{}'", name);
        return null;
    }

    // ---------- building / sending ----------

    /** @return a new event; rsn / accountHash are null when the player is not available (submit() then skips it). */
    private GameEvent base(String type)
    {
        GameEvent ev = new GameEvent();
        ev.id = UUID.randomUUID().toString();
        ev.sourceType = type;
        ev.occurredAt = Instant.now().toString();
        ev.world = client.getWorld();
        Player me = client.getLocalPlayer();
        ev.rsn = me == null ? null : Sanitizer.normalizeRsn(me.getName());
        long hash = client.getAccountHash();
        ev.accountHash = hash == -1 ? null : Long.toString(hash);
        return ev;
    }

    private void addItems(GameEvent ev, Collection<ItemStack> stacks)
    {
        if (stacks == null) return;
        for (ItemStack s : stacks)
        {
            if (s.getQuantity() < 1) continue;
            int id = itemManager.canonicalize(s.getId());
            ev.addItem(id, s.getQuantity());
            activityWatcher.onLoot(id, client.getTickCount());
        }
    }

    private void submit(GameEvent ev, boolean maybeScreenshot)
    {
        if (!running || queue == null || !Sanitizer.validRsn(ev.rsn) || ev.accountHash == null || api == null || !api.configured())
        {
            return;
        }
        // The server rejects item-based events without items; do not queue what can never be accepted.
        boolean needsItems = GameEvent.NPC.equals(ev.sourceType) || GameEvent.RAID_CHEST.equals(ev.sourceType)
            || GameEvent.CLUE.equals(ev.sourceType) || GameEvent.COLLECTION_LOG.equals(ev.sourceType) || GameEvent.PET.equals(ev.sourceType);
        if (needsItems && (ev.items == null || ev.items.isEmpty()))
        {
            return;
        }
        if (!dedup.firstSeen(EventDeduplicator.signature(ev, client.getTickCount()), System.currentTimeMillis()))
        {
            return;
        }
        log.debug("queue event {} {}", ev.sourceType, ev.label());
        if (maybeScreenshot && config.screenshotOnMatch() && couldCount(ev))
        {
            captureScreenshot(ev.id);
        }
        List<QueuedEvent> evicted = queue.add(new QueuedEvent(ev, System.currentTimeMillis()));
        for (QueuedEvent q : evicted) notice("Queue full, dropped oldest event: " + q.event.label(), true);
        notifyPanel(p -> p.setQueueSize(queue == null ? 0 : queue.size(), null));
        scheduleQueueDrain(0);
    }

    private void scheduleQueueDrain(long delayMillis)
    {
        if (!running) return;
        if (queueFuture != null) queueFuture.cancel(false);
        queueFuture = executor.schedule(() -> {
            QueueProcessor p = processor;
            if (!running || p == null) return;
            long next;
            try
            {
                next = p.drain();
            }
            catch (RuntimeException ex)
            {
                log.debug("queue drain failed", ex);
                next = 60_000;
            }
            if (next >= 0) scheduleQueueDrain(next);
        }, delayMillis, TimeUnit.MILLISECONDS);
    }

    // ---------- screenshots (kept in memory; uploaded only after server confirms a match) ----------

    /**
     * Could this event count for an open task on the current board? Only those get a screenshot, so ordinary
     * drops no longer fill the few screenshot slots before the drop that matters (the server still decides).
     */
    private boolean couldCount(GameEvent ev)
    {
        ApiModels.BoardResponse b = currentBoard();
        if (b == null || b.tiles == null) return true;
        // finished tiles count too: drops keep counting (with proof) until the bingo is over (owner, 2026-11-11)
        for (ApiModels.Tile t : b.tiles)
        {
            if (t == null || t.tasks == null) continue;
            for (ApiModels.Task k : t.tasks)
            {
                if (k == null) continue;
                if (k.itemIds != null && !k.itemIds.isEmpty())
                {
                    if (ev.items == null) continue;
                    for (GameEvent.Item it : ev.items) if (k.itemIds.contains(it.itemId)) return true;
                }
                else if (k.sourceType != null && k.sourceType.equals(ev.sourceType))
                {
                    return true;
                }
            }
        }
        // secret tiles hide their tasks: their items come as hiddenItemIds
        if (b.hiddenItemIds != null && ev.items != null)
        {
            for (GameEvent.Item it : ev.items) if (b.hiddenItemIds.contains(it.itemId)) return true;
        }
        return false;
    }

    private void captureScreenshot(String eventId)
    {
        // only in game, and never with the bank PIN keypad on screen (its layout would be in the proof)
        if (client.getGameState() != GameState.LOGGED_IN || bankPinOpen()) return;
        // marked before the frame arrives: the server's answer can come back first, and the upload waits for this
        shotsInProgress.add(eventId);
        // Wait ~2 game ticks before taking it (owner, 2026-11-12): by then the drop's chat message, the loot on the
        // ground and the collection log pop-up are all on screen, so the proof shows the drop clearly.
        executor.schedule(() -> requestDropFrame(eventId), SCREENSHOT_DELAY_MS, TimeUnit.MILLISECONDS);
    }

    /** milliseconds between spotting a drop and taking its screenshot */
    private static final long SCREENSHOT_DELAY_MS = 1200;
    /** minimum time between "Send screenshot" proofs */
    private static final long SCREENSHOT_COOLDOWN_MS = 5000;
    private volatile long lastProofShotAt;

    private void requestDropFrame(String eventId)
    {
        if (!running) { shotsInProgress.remove(eventId); return; }
        drawManager.requestNextFrameListener(image -> {
            if (client.getGameState() != GameState.LOGGED_IN || bankPinOpen())
            {
                shotsInProgress.remove(eventId);
                return;
            }
            // the player's name, read on the client thread as the frame is captured
            String player = client.getLocalPlayer() == null ? null : client.getLocalPlayer().getName();
            executor.execute(() -> {
            try
            {
                BufferedImage img = ImageUtil.bufferedImageFromImage(image);
                if (config.screenshotSidebar())
                {
                    img = withWindow(img);
                }
                java.time.ZonedDateTime taken = java.time.ZonedDateTime.now();
                // stored unstamped; each team's copy is stamped with its own code and tiles when it is sent
                byte[] shot = ScreenshotEncode.jpeg(img, ApiClient.MAX_SCREENSHOT_BYTES);
                if (shot == null) return;
                long now = System.currentTimeMillis();
                screenshots.values().removeIf(s -> now - s.at > SCREENSHOT_TTL_MILLIS);
                // full: drop the oldest instead of skipping this one (the newest drop is the likeliest to count)
                while (screenshots.size() >= MAX_SCREENSHOTS)
                {
                    String oldest = null;
                    long at = Long.MAX_VALUE;
                    for (Map.Entry<String, Screenshot> s : screenshots.entrySet()) if (s.getValue().at < at) { at = s.getValue().at; oldest = s.getKey(); }
                    if (oldest == null) break;
                    screenshots.remove(oldest);
                }
                screenshots.put(eventId, new Screenshot(shot, now, player, taken));
            }
            catch (Exception ex)
            {
                log.debug("screenshot failed", ex);
            }
            finally
            {
                shotsInProgress.remove(eventId);
            }
        });
        });
    }

    /** Event ids whose screenshot is being taken right now (requested, not yet stored or given up). */
    private final java.util.Set<String> shotsInProgress = ConcurrentHashMap.newKeySet();

    /**
     * "Send screenshot as proof" in the side panel: takes the next game frame (stamped like drop proof) and sends it
     * as a new proof for that task, waiting for review like proof added on the website. Any thread.
     */
    void sendScreenshotProof(String taskId, String what)
    {
        sendScreenshotProof(null, taskId, what, null);
    }

    /**
     * As above, for the board the tile card came from (null = the selected board); tileName is stamped on the shot
     * with the player's name, that bingo's code and the time.
     */
    void sendScreenshotProof(String teamBoardId, String taskId, String what, String tileName)
    {
        // 5-second cooldown between proof screenshots (owner, 2026-11-12)
        long since = System.currentTimeMillis() - lastProofShotAt;
        if (since < SCREENSHOT_COOLDOWN_MS)
        {
            notice("Wait " + ((SCREENSHOT_COOLDOWN_MS - since + 999) / 1000) + "s before the next screenshot.", true);
            return;
        }
        String team = teamBoardId != null && !teamBoardId.isEmpty() ? teamBoardId : config.activeBoardId();
        ApiClient a = api;
        if (taskId == null || team == null || team.isEmpty() || a == null || !a.configured())
        {
            notice("Connect the plugin to your team first.", true);
            return;
        }
        if (client.getGameState() != GameState.LOGGED_IN || bankPinOpen())
        {
            notice("Log in (and close the bank PIN) to take a screenshot.", true);
            return;
        }
        lastProofShotAt = System.currentTimeMillis();
        drawManager.requestNextFrameListener(image -> {
            // read the player's name here, on the client thread, as the frame is captured
            String player = client.getLocalPlayer() == null ? null : client.getLocalPlayer().getName();
            executor.execute(() -> {
            try
            {
                BufferedImage img = ImageUtil.bufferedImageFromImage(image);
                if (config.screenshotSidebar()) img = withWindow(img);
                ApiModels.BoardResponse cb = currentBoard();
                String kw = cb != null && cb.event != null ? cb.event.keyword : null;
                java.time.ZonedDateTime taken = java.time.ZonedDateTime.now();
                img = ScreenshotStamp.stamp(img, kw, taken, player, tileName == null ? what : tileName);
                byte[] shot = ScreenshotEncode.jpeg(img, ApiClient.MAX_SCREENSHOT_BYTES);
                if (shot == null) return;
                ApiResult<ApiModels.ProofResponse> r = a.uploadTaskScreenshot(team, taskId, shot, kw,
                    taken.withZoneSameInstant(java.time.ZoneOffset.UTC).toInstant().toString(), what);
                if (r.ok())
                {
                    notice("Screenshot sent for " + what + " - waiting for review.", true);
                    boardVersions.clear();
                    pollBoardSafely();
                }
                else if (r.status == 404)
                {
                    // the selected board is gone (team deleted, or the bingo is not live yet): reload the list
                    notice("That board isn't available any more. Pick your board again in the ForgeBingo panel.", true);
                    boardVersions.clear();
                    pollBoardSafely();
                }
                else if ("invalid_targets".equals(r.errorCode))
                {
                    notice("The server doesn't take plugin screenshots yet - add proof on the website for now.", true);
                }
                else if ("too_soon".equals(r.errorCode))
                {
                    notice("Screenshot already sent a moment ago.", true);
                }
                else
                {
                    notice("Screenshot not sent: " + r.describe(), true);
                }
            }
            catch (Exception ex)
            {
                log.debug("screenshot proof failed", ex);
                notice("Screenshot not sent: something went wrong taking it.", true);
            }
            });
        });
    }

    /** The bank PIN keypad (interface group 213) is showing. */
    private boolean bankPinOpen()
    {
        net.runelite.api.widgets.Widget pin = client.getWidget(BANK_PIN_GROUP, 0);
        return pin != null && !pin.isHidden();
    }

    private static final int BANK_PIN_GROUP = 213;

    /**
     * Opt-in whole-window shot: paints the RuneLite window (sidebar, plugin panel) on the Swing thread and lays the
     * game frame over the canvas area (the GPU-drawn game paints blank through Swing). Any failure keeps the game shot.
     */
    private BufferedImage withWindow(BufferedImage game)
    {
        final java.awt.Canvas canvas = client.getCanvas();
        if (canvas == null) return game;
        final BufferedImage[] window = new BufferedImage[1];
        final java.awt.Rectangle[] at = new java.awt.Rectangle[1];
        try
        {
            SwingUtilities.invokeAndWait(() -> {
                // only while our own panel is the open one: another plugin's panel (notes, bank value) stays out
                if (panel == null || !panel.isShowing()) return;
                java.awt.Window w = SwingUtilities.getWindowAncestor(canvas);
                if (!(w instanceof javax.swing.RootPaneContainer)) return;
                java.awt.Container pane = ((javax.swing.RootPaneContainer) w).getContentPane();
                int pw = pane.getWidth();
                int ph = pane.getHeight();
                if (pw <= 0 || ph <= 0 || pw > WindowShot.MAX_SIDE || ph > WindowShot.MAX_SIDE) return;
                BufferedImage shot = new BufferedImage(pw, ph, BufferedImage.TYPE_INT_RGB);
                java.awt.Graphics2D g = shot.createGraphics();
                try
                {
                    pane.paint(g);
                }
                finally
                {
                    g.dispose();
                }
                java.awt.Point p = SwingUtilities.convertPoint(canvas, 0, 0, pane);
                window[0] = shot;
                at[0] = new java.awt.Rectangle(p.x, p.y, canvas.getWidth(), canvas.getHeight());
            });
        }
        catch (Exception ex)
        {
            log.debug("window screenshot failed", ex);
            return game;
        }
        if (window[0] == null || at[0] == null) return game;
        return WindowShot.compose(window[0], game, at[0].x, at[0].y, at[0].width, at[0].height);
    }

    private void maybeUploadScreenshot(GameEvent event, ApiModels.EventResult result)
    {
        maybeUploadScreenshot(event, result, 0);
    }

    /**
     * The server often answers before the screenshot of the same drop is stored (it is taken on the next frame and
     * saved on this same worker), so when one is still being taken, try again shortly instead of giving up. This
     * race is why almost no drop screenshots were uploaded (2026-11-11).
     */
    private void maybeUploadScreenshot(GameEvent event, ApiModels.EventResult result, int attempt)
    {
        if (!config.screenshotOnMatch() || result == null || !result.isMatched() || result.duplicate)
        {
            screenshots.remove(event.id);
            return;
        }
        Screenshot s = screenshots.remove(event.id);
        if (s == null)
        {
            if (shotsInProgress.contains(event.id) && attempt < 20 && running)
            {
                executor.schedule(() -> maybeUploadScreenshot(event, result, attempt + 1), 250, TimeUnit.MILLISECONDS);
            }
            return;
        }
        // One upload per team, attached to that team's submissions from matched[].submissionId.
        Map<String, List<String>> byTeam = new java.util.LinkedHashMap<>();
        // the file is named after the (first) task this drop counted for, e.g. big-boners_3f2a9c1e.png
        Map<String, String> labels = new java.util.HashMap<>();
        Map<String, String> taskNames = new java.util.HashMap<>();
        ApiModels.BoardResponse cb = currentBoard();
        if (cb != null && cb.tiles != null)
        {
            for (ApiModels.Tile t : cb.tiles)
            {
                if (t != null && t.tasks != null) for (ApiModels.Task k : t.tasks) if (k != null && k.id != null) taskNames.put(k.id, k.description);
            }
        }
        for (ApiModels.Match m : result.matched)
        {
            if (m.teamId == null || m.submissionId == null) continue;
            byTeam.computeIfAbsent(m.teamId, k -> new ArrayList<>());
            List<String> ids = byTeam.get(m.teamId);
            if (!ids.contains(m.submissionId) && ids.size() < 25) ids.add(m.submissionId);
            String name = m.taskId == null ? null : taskNames.get(m.taskId);
            if (name == null || name.isEmpty()) name = m.tileId == null ? null : tileTitles.get(m.tileId);
            if (name != null && !name.isEmpty()) labels.putIfAbsent(m.teamId, name);
        }
        // tiles this drop counted for, per team (a player can be on several teams in different bingos at once)
        Map<String, List<String>> tilesByTeam = new java.util.HashMap<>();
        for (ApiModels.Match m : result.matched)
        {
            if (m.teamId != null && m.tileId != null) tilesByTeam.computeIfAbsent(m.teamId, k -> new ArrayList<>()).add(m.tileId);
        }
        String capturedAt = s.taken.withZoneSameInstant(java.time.ZoneOffset.UTC).toInstant().toString();
        for (Map.Entry<String, List<String>> t : byTeam.entrySet())
        {
            try
            {
                // that team's own board: its bingo's code word and the names of the tiles the drop counted for
                ApiResult<ApiModels.BoardResponse> br = api.board(t.getKey());
                ApiModels.BoardResponse tb = br.ok() ? br.body : null;
                String kw = tb != null && tb.event != null ? tb.event.keyword : null;
                List<String> names = new ArrayList<>();
                for (String tileId : tilesByTeam.getOrDefault(t.getKey(), java.util.Collections.emptyList()))
                {
                    String title = null;
                    if (tb != null && tb.tiles != null) for (ApiModels.Tile x : tb.tiles) if (x != null && tileId.equals(x.id)) { title = TileInfo.shownTitle(x); break; }
                    if (title == null) title = tileTitles.get(tileId);
                    if (title != null && !title.isEmpty() && !names.contains(title)) names.add(title);
                }
                String tiles = names.isEmpty() ? null : names.size() <= 2 ? String.join(", ", names) : names.get(0) + ", " + names.get(1) + " +" + (names.size() - 2);
                BufferedImage img = ImageIO.read(new java.io.ByteArrayInputStream(s.raw));
                if (img == null) continue;
                byte[] stamped = ScreenshotEncode.jpeg(ScreenshotStamp.stamp(img, kw, s.taken, s.player, tiles), ApiClient.MAX_SCREENSHOT_BYTES);
                if (stamped == null) continue;
                ApiResult<ApiModels.ProofResponse> r = api.uploadProof(t.getKey(), stamped, t.getValue(), kw, capturedAt, labels.get(t.getKey()));
                if (!r.ok())
                {
                    notice("Screenshot upload failed: " + r.describe(), true);
                }
            }
            catch (java.io.IOException ex)
            {
                log.debug("screenshot stamp failed", ex);
            }
        }
    }

    // ---------- user-visible notices ----------

    private void notice(String text, boolean important)
    {
        notifyPanel(p -> p.addNotice(text));
        if (config.chatNotices() && important && client.getGameState() == GameState.LOGGED_IN)
        {
            clientThread.invoke(() -> chatMessageManager.queue(QueuedMessage.builder()
                .type(ChatMessageType.CONSOLE)
                .runeLiteFormattedMessage(net.runelite.client.util.ColorUtil.wrapWithColorTag(
                    "[ForgeBingo] " + text.replace("<", "").replace(">", ""),
                    config.chatColor() == null ? ForgeBingoConfig.DEFAULT_CHAT_COLOR : config.chatColor()))
                .build()));
        }
    }

    private final class QueueListener implements QueueProcessor.Listener
    {
        @Override
        public void onAccepted(GameEvent event, ApiModels.EventResult result)
        {
            if (result != null && result.automationDisabled)
            {
                screenshots.remove(event.id);
                if (!automationNoticeShown)
                {
                    automationNoticeShown = true;
                    notice("Automatic reporting is currently disabled by the ForgeBingo admins; events are not recorded.", true);
                }
                return;
            }
            automationNoticeShown = false;
            if (result != null && result.isMatched() && !result.duplicate)
            {
                // tiles that were already finished before this drop: it still counts, but no second celebration
                // what was already finished before this drop (no second celebration), and task names for the messages
                java.util.Set<String> wasDone = new java.util.HashSet<>();
                java.util.Set<String> taskWasDone = new java.util.HashSet<>();
                Map<String, String> taskNames = new java.util.HashMap<>();
                ApiModels.BoardResponse before = currentBoard();
                if (before != null && before.tiles != null)
                {
                    for (ApiModels.Tile t : before.tiles)
                    {
                        if (t == null) continue;
                        if (t.completed && t.id != null) wasDone.add(t.id);
                        if (t.tasks != null) for (ApiModels.Task k : t.tasks)
                        {
                            if (k == null || k.id == null) continue;
                            if (k.completed) taskWasDone.add(k.id);
                            taskNames.put(k.id, k.description);
                        }
                    }
                }
                // a match's "completed" is its TASK; the tile is finished when matchedTiles says so
                java.util.Set<String> tileNowDone = new java.util.HashSet<>();
                if (result.matchedTiles != null)
                {
                    for (ApiModels.MatchedTile mt : result.matchedTiles) if (mt != null && mt.completed && mt.tileId != null) tileNowDone.add(mt.tileId);
                }
                java.util.Set<String> announced = new java.util.HashSet<>();
                for (ApiModels.Match m : result.matched)
                {
                    String title = m.tileId == null ? null : tileTitles.get(m.tileId);
                    String tileName = title == null ? "a tile" : title;
                    String state = "approved".equals(m.status) ? ""
                        : Boolean.FALSE.equals(m.verified) ? " - waiting for review (your name isn't verified yet)" : " - waiting for review";
                    if (m.tileId != null && wasDone.contains(m.tileId))
                    {
                        notice("Extra drop logged for " + tileName + " (already done)" + state, config.chatNotices());
                        continue;
                    }
                    String progress = m.requiredQuantity > 0 ? " (" + Math.min(m.currentQuantity, m.requiredQuantity) + "/" + m.requiredQuantity + ")" : "";
                    if (m.tileId != null && tileNowDone.contains(m.tileId))
                    {
                        if (announced.add("tile:" + m.tileId)) notice("Tile complete: " + tileName + state, config.chatNotices());
                    }
                    else if (m.completed && m.taskId != null && !taskWasDone.contains(m.taskId))
                    {
                        String task = taskNames.get(m.taskId);
                        String what = task == null || task.isEmpty() ? tileName : task + " (" + tileName + ")";
                        if (announced.add("task:" + m.taskId))
                        {
                            notice("Task complete: " + what + state, config.chatNotices());
                            if (config.effects()) effects.push(EffectsOverlay.Kind.TASK, task == null || task.isEmpty() ? tileName : task);
                        }
                    }
                    else
                    {
                        notice("Counted: " + tileName + progress + state, config.chatNotices());
                    }
                }
                maybeUploadScreenshot(event, result);
                for (String tileId : tileNowDone)
                {
                    if (!wasDone.contains(tileId)) celebrateTile(config.activeBoardId(), tileId, tileTitles.get(tileId));
                }
                boardVersions.clear();
                executor.execute(ForgeBingoPlugin.this::pollBoardSafely);
            }
            else
            {
                screenshots.remove(event.id);
            }
        }

        @Override
        public void onDropped(GameEvent event, String reason)
        {
            screenshots.remove(event.id);
            notice("Dropped " + event.sourceType + " event (" + event.label() + "): " + reason, true);
            if (reason != null && reason.contains("not_a_member"))
            {
                boardVersions.clear();
                executor.execute(ForgeBingoPlugin.this::pollBoardSafely);
            }
        }

        @Override
        public void onAuthProblem(String message)
        {
            notifyPanel(p -> p.setStatus(false, message));
            notice(message, true);
        }

        @Override
        public void onQueueChanged(int size, String lastError)
        {
            notifyPanel(p -> p.setQueueSize(size, lastError));
        }
    }
}

package com.forgebingo;

import com.forgebingo.core.ImpSprite;
import java.awt.AWTEvent;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.HierarchyEvent;
import java.awt.event.HierarchyListener;
import java.awt.event.MouseEvent;
import java.awt.geom.AffineTransform;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import javax.swing.JComponent;
import javax.swing.JLayer;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.plaf.LayerUI;

/**
 * The website's little imps, wandering over the side panel: they walk along the tops of the cards, hop between
 * them, climb the panel's edges and stop for a chat (a port of apps/web/src/features/fun/Imps.tsx).
 * Painted over the scrolling column by a JLayer, in the column's own coordinates, so they stay on the card they
 * stand on when you scroll. They never take clicks away from the panel. The timer only runs while the panel is
 * on screen and imps are switched on.
 */
final class PanelImps extends LayerUI<JComponent>
{
    /** client property: this component's top edge is somewhere an imp can stand */
    static final String PLATFORM = "forgebingo.impPlatform";

    private static final int COUNT = 2;
    private static final float SPEED = 26f;
    private static final float GRAVITY = 1400f;
    /** body size the physics uses (the sprite itself is 42 x 34 with room for hats and staffs) */
    private static final int BODY_W = 22;
    private static final int EDGE = 9;

    private enum Mode { WALK, IDLE, AIR, CHAT, CLIMB }

    private static final class Imp
    {
        float x, y, vx, vy;
        int dir = 1;
        Mode mode = Mode.AIR;
        float t, life, chatCd, squash, px, seekT, spark, sparkAge = 9f, bubbleT;
        int seek, side = 1, cdir = -1;
        String bubble = "";
        ImpSprite.Hat hat = ImpSprite.Hat.NONE;
        ImpSprite.Item item = ImpSprite.Item.NONE;
        boolean rare;
        float sparkX, sparkY;
        Rectangle last;
    }

    private final Random rnd = new Random();
    private final List<Imp> imps = new ArrayList<>();
    private final List<int[]> plats = new ArrayList<>(); // left, right, y
    private final Timer timer = new Timer(33, e -> frame());
    private JLayer<? extends JComponent> layer;
    private boolean enabled = true;
    private long lastNanos;
    private float sincePlats = 99f;
    private float clock;

    private final HierarchyListener showing = e -> {
        if ((e.getChangeFlags() & HierarchyEvent.SHOWING_CHANGED) != 0) sync();
    };

    @Override
    @SuppressWarnings("unchecked")
    public void installUI(JComponent c)
    {
        super.installUI(c);
        layer = (JLayer<? extends JComponent>) c;
        layer.setLayerEventMask(AWTEvent.MOUSE_EVENT_MASK);
        layer.addHierarchyListener(showing);
        sync();
    }

    @Override
    public void uninstallUI(JComponent c)
    {
        timer.stop();
        if (layer != null)
        {
            layer.setLayerEventMask(0);
            layer.removeHierarchyListener(showing);
        }
        layer = null;
        super.uninstallUI(c);
    }

    void setEnabled(boolean on)
    {
        enabled = on;
        if (!on) imps.clear();
        sync();
        if (layer != null) layer.repaint();
    }

    /** Stops everything for good (plugin shut down). */
    void dispose()
    {
        enabled = false;
        timer.stop();
        imps.clear();
    }

    private void sync()
    {
        boolean run = enabled && layer != null && layer.isShowing();
        if (run && !timer.isRunning())
        {
            lastNanos = 0;
            timer.start();
        }
        else if (!run && timer.isRunning())
        {
            timer.stop();
        }
    }

    // ------------------------------------------------------------------ world

    private float rnd(float a, float b)
    {
        return a + rnd.nextFloat() * (b - a);
    }

    private int width()
    {
        return Math.max(60, layer.getWidth());
    }

    private int height()
    {
        return Math.max(60, layer.getHeight());
    }

    /** Most imps are plain; a few wear hats and the rarest carry famous items (same odds as the website). */
    private void rollLook(Imp m)
    {
        m.hat = ImpSprite.Hat.NONE;
        m.item = ImpSprite.Item.NONE;
        float r = rnd.nextFloat();
        if (r < 1 / 50f) m.hat = ImpSprite.Hat.CHEF;
        else if (r < 2 / 50f) m.hat = ImpSprite.Hat.WIZARD;
        else if (r < 2 / 50f + 1 / 400f) m.item = ImpSprite.Item.FIRE_STAFF;
        else if (r < 2 / 50f + 2 / 400f) m.item = ImpSprite.Item.AYAK;
        else if (r < 2 / 50f + 3 / 400f) m.item = ImpSprite.Item.SOULREAPER;
        else if (r < 2 / 50f + 3 / 400f + 1 / 200f) m.hat = ImpSprite.Hat.SANTA;
        else if (r < 2 / 50f + 3 / 400f + 2 / 200f) m.hat = ImpSprite.Hat.BUNNY;
        m.rare = m.hat != ImpSprite.Hat.NONE || m.item != ImpSprite.Item.NONE;
    }

    /** Drops a fresh imp in from above the part of the panel you can see. */
    private void spawn(Imp m)
    {
        Rectangle view = layer.getVisibleRect();
        m.x = rnd(20, Math.max(40, width() - 20));
        m.y = view.y - rnd(30, 110);
        m.vx = 0;
        m.vy = 0;
        m.dir = rnd.nextBoolean() ? 1 : -1;
        m.mode = Mode.AIR;
        m.t = rnd(1, 3);
        m.seek = 0;
        m.seekT = 0;
        m.chatCd = rnd(2, 6);
        m.squash = 0;
        m.life = rnd(150, 400);
        m.spark = rnd(2, 6);
        m.bubble = "";
        rollLook(m);
    }

    private void refreshPlatforms()
    {
        plats.clear();
        JComponent view = layer.getView();
        int vw = width();
        if (view != null) collect(view, view, vw, 0);
        plats.add(new int[] {6, vw - 6, height() - 2});
    }

    private void collect(Container root, Container parent, int vw, int depth)
    {
        if (depth > 6 || plats.size() > 200) return;
        for (Component c : parent.getComponents())
        {
            if (!c.isVisible() || c.getWidth() <= 0 || c.getHeight() <= 0) continue;
            if (c instanceof JComponent && Boolean.TRUE.equals(((JComponent) c).getClientProperty(PLATFORM)))
            {
                Rectangle r = SwingUtilities.convertRectangle(parent, c.getBounds(), root);
                int l = Math.max(r.x, 6);
                int rr = Math.min(r.x + r.width, vw - 6);
                if (rr - l >= 30 && r.height >= 8 && r.y >= 14) plats.add(new int[] {l, rr, r.y});
            }
            if (c instanceof Container) collect(root, (Container) c, vw, depth + 1);
        }
    }

    private int[] support(float x, float y)
    {
        for (int[] p : plats) if (x >= p[0] - 3 && x <= p[1] + 3 && Math.abs(p[2] - y) <= 8) return p;
        return null;
    }

    private void launch(Imp m, float vx, float vy)
    {
        m.mode = Mode.AIR;
        m.vx = vx;
        m.vy = vy;
        m.squash = 1;
    }

    private boolean jumpToNearby(Imp m)
    {
        List<int[]> cands = new ArrayList<>();
        for (int[] p : plats)
        {
            float cx = Math.min(Math.max(m.x, p[0]), p[1]);
            float dy = m.y - p[2];
            if (Math.abs(cx - m.x) < 200 && dy < 130 && dy > -190 && Math.abs(dy) > 3) cands.add(p);
        }
        if (cands.isEmpty()) return false;
        int[] p = cands.get(rnd.nextInt(cands.size()));
        float tx = rnd(p[0] + 4, Math.max(p[0] + 5, p[1] - 4));
        float up = m.y - p[2];
        float vy0 = -(float) Math.sqrt(2 * GRAVITY * (Math.max(0, up) + 24));
        float t = (float) ((-vy0 + Math.sqrt(vy0 * vy0 - 2 * GRAVITY * up)) / GRAVITY);
        float vx = Math.max(-280, Math.min(280, (tx - m.x) / Math.max(0.05f, t)));
        m.dir = vx < 0 ? -1 : 1;
        launch(m, vx, vy0);
        return true;
    }

    private void startClimb(Imp m, int side)
    {
        Rectangle view = layer.getVisibleRect();
        m.mode = Mode.CLIMB;
        m.side = side;
        m.cdir = m.y - view.y > view.height * 0.5f ? -1 : 1;
        m.t = rnd(2.5f, 5);
        m.seek = 0;
    }

    private void step(Imp m, float dt)
    {
        int vw = width();
        int docH = height();
        m.squash += (0 - m.squash) * Math.min(1, dt * 9);
        m.life -= dt;
        m.chatCd -= dt;
        m.sparkAge += dt;
        if (m.bubbleT > 0)
        {
            m.bubbleT -= dt;
            if (m.bubbleT <= 0 && m.mode != Mode.CHAT) m.bubble = "";
        }
        if (m.seekT > 0)
        {
            m.seekT -= dt;
            if (m.seekT <= 0) m.seek = 0;
        }
        if (m.mode == Mode.WALK || m.mode == Mode.IDLE)
        {
            int[] p = support(m.x, m.y);
            if (p == null)
            {
                m.mode = Mode.AIR;
                m.vx = 0;
                m.vy = 0;
                return;
            }
            m.y = p[2];
            m.t -= dt;
            if (m.mode == Mode.IDLE)
            {
                if (m.t <= 0)
                {
                    m.mode = Mode.WALK;
                    m.t = rnd(1.5f, 4);
                }
                return;
            }
            m.px += dt * 8;
            float nx = m.x + m.dir * SPEED * dt;
            if (nx > p[1] - 3 || nx < p[0] + 3)
            {
                boolean atEdge = nx > p[1] - 3 ? p[1] >= vw - 6.5f : p[0] <= 6.5f;
                if (m.seek == m.dir && atEdge)
                {
                    startClimb(m, m.dir);
                    return;
                }
                if (m.seek == m.dir)
                {
                    launch(m, m.dir * 110, -220);
                    return;
                }
                if (rnd.nextFloat() < 0.45f && jumpToNearby(m)) return;
                m.dir = -m.dir;
                return;
            }
            m.x = nx;
            if (m.t <= 0)
            {
                float r = rnd.nextFloat();
                m.t = rnd(1.5f, 4);
                if (r < 0.2f) launch(m, m.dir * 30, -260);
                else if (r < 0.42f)
                {
                    if (!jumpToNearby(m)) m.dir = -m.dir;
                }
                else if (r < 0.52f)
                {
                    m.seek = rnd.nextBoolean() ? -1 : 1;
                    m.dir = m.seek;
                    m.seekT = 14;
                }
                else if (r < 0.66f) m.dir = -m.dir;
                else
                {
                    m.mode = Mode.IDLE;
                    m.t = rnd(0.8f, 2.6f);
                }
            }
            if (m.life <= 0) spawn(m);
        }
        else if (m.mode == Mode.AIR)
        {
            m.vy += GRAVITY * dt;
            float py = m.y;
            m.x += m.vx * dt;
            m.y += m.vy * dt;
            if (m.x <= EDGE || m.x >= vw - EDGE)
            {
                m.x = Math.min(Math.max(m.x, EDGE), vw - EDGE);
                if (m.seek != 0 && m.y > 40 && m.y < docH - 14)
                {
                    startClimb(m, m.x < vw / 2f ? -1 : 1);
                    return;
                }
                m.vx = -m.vx * 0.5f;
            }
            if (m.vy > 0)
            {
                for (int[] p : plats)
                {
                    if (m.x >= p[0] - 2 && m.x <= p[1] + 2 && py <= p[2] + 1 && m.y >= p[2])
                    {
                        m.y = p[2];
                        m.vx = 0;
                        m.vy = 0;
                        m.mode = Mode.WALK;
                        m.t = rnd(1, 3);
                        m.squash = -1;
                        break;
                    }
                }
            }
            if (m.y > docH + 30)
            {
                m.y = docH - 2;
                m.mode = Mode.WALK;
                m.vx = 0;
                m.vy = 0;
            }
        }
        else if (m.mode == Mode.CLIMB)
        {
            m.x = m.side == -1 ? EDGE : vw - EDGE;
            m.y += m.cdir * 22 * dt;
            m.px += dt * 8;
            m.t -= dt;
            if (m.y < 40) m.cdir = 1;
            if (m.y > docH - 4)
            {
                m.y = docH - 2;
                m.t = 0;
            }
            if (m.t <= 0)
            {
                m.dir = -m.side;
                launch(m, -m.side * 100, -300);
                m.t = rnd(1, 3);
            }
        }
        else
        {
            m.t -= dt;
            if (m.t <= 0)
            {
                m.mode = Mode.WALK;
                m.t = rnd(1, 3);
                m.chatCd = rnd(6, 12);
                m.dir = rnd.nextBoolean() ? 1 : -1;
                m.bubble = "";
            }
        }
    }

    private void frame()
    {
        if (layer == null || !layer.isShowing())
        {
            sync();
            return;
        }
        long now = System.nanoTime();
        float dt = lastNanos == 0 ? 0.033f : Math.min((now - lastNanos) / 1e9f, 0.05f);
        lastNanos = now;
        advance(dt);
    }

    /** One step of the imps' world (the timer calls this; the offline preview calls it directly). */
    void advance(float dt)
    {
        if (layer == null || !enabled) return;
        clock += dt;
        sincePlats += dt;
        if (sincePlats > 1.2f)
        {
            sincePlats = 0;
            refreshPlatforms();
        }
        while (imps.size() < COUNT)
        {
            Imp m = new Imp();
            spawn(m);
            imps.add(m);
        }
        for (Imp m : imps) step(m, dt);
        // hanging out: two imps that meet stop for a chat
        for (int i = 0; i < imps.size(); i++)
        {
            Imp a = imps.get(i);
            if ((a.mode != Mode.WALK && a.mode != Mode.IDLE) || a.chatCd > 0) continue;
            for (int j = i + 1; j < imps.size(); j++)
            {
                Imp b = imps.get(j);
                if ((b.mode != Mode.WALK && b.mode != Mode.IDLE) || b.chatCd > 0) continue;
                if (Math.abs(a.x - b.x) < 26 && Math.abs(a.y - b.y) < 4 && rnd.nextFloat() < dt * 1.5f)
                {
                    float d = rnd(1.2f, 3);
                    a.mode = Mode.CHAT;
                    b.mode = Mode.CHAT;
                    a.t = d;
                    b.t = d;
                    a.dir = a.x <= b.x ? 1 : -1;
                    b.dir = -a.dir;
                    a.bubble = rnd.nextBoolean() ? "heart" : "...";
                    b.bubble = rnd.nextBoolean() ? "note" : "...";
                    break;
                }
            }
        }
        for (Imp m : imps)
        {
            if (m.rare)
            {
                m.spark -= dt;
                if (m.spark <= 0)
                {
                    m.spark = rnd(2.5f, 5);
                    m.sparkAge = 0;
                    m.sparkX = rnd(-12, 10);
                    m.sparkY = rnd(-26, -6);
                }
            }
            Rectangle r = new Rectangle(Math.round(m.x) - 30, Math.round(m.y) - 50, 60, 58);
            layer.repaint(m.last == null ? r : r.union(m.last));
            m.last = r;
        }
    }

    // ------------------------------------------------------------------ input (a poke makes an imp jump)

    @Override
    protected void processMouseEvent(MouseEvent e, JLayer<? extends JComponent> l)
    {
        if (e.getID() != MouseEvent.MOUSE_PRESSED || imps.isEmpty()) return;
        Point p = SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), l);
        for (Imp m : imps)
        {
            if (m.mode == Mode.AIR) continue;
            if (Math.abs(p.x - m.x) <= BODY_W / 2 + 2 && p.y <= m.y + 1 && p.y >= m.y - 22)
            {
                m.bubble = "!";
                m.bubbleT = 0.9f;
                m.dir = p.x < m.x ? 1 : -1;
                launch(m, m.dir * rnd(40, 90), -rnd(280, 360));
                return;
            }
        }
    }

    // ------------------------------------------------------------------ painting

    @Override
    public void paint(Graphics g, JComponent c)
    {
        super.paint(g, c);
        if (!enabled || imps.isEmpty()) return;
        Graphics2D g2 = (Graphics2D) g.create();
        try
        {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
            for (Imp m : imps) paintImp(g2, m);
        }
        finally
        {
            g2.dispose();
        }
    }

    private void paintImp(Graphics2D g, Imp m)
    {
        boolean moving = m.mode == Mode.WALK || m.mode == Mode.CLIMB;
        boolean stepUp = moving && ((int) Math.floor(m.px)) % 2 == 0;
        int frame = stepUp || m.mode == Mode.AIR ? 1 : 0;
        BufferedImage img = ImpSprite.image(m.hat, m.item, frame);
        float x = Math.round(m.x);
        float y = Math.round(m.y);

        if (m.mode != Mode.AIR && m.mode != Mode.CLIMB)
        {
            g.setColor(new Color(0, 0, 0, 70));
            g.fill(new Ellipse2D.Float(x - 8, y - 2, 16, 3.5f));
        }

        AffineTransform old = g.getTransform();
        g.translate(x, y);
        if (m.mode == Mode.CLIMB)
        {
            // feet against the panel's edge, head pointing inward
            g.rotate(m.side == -1 ? Math.PI / 2 : -Math.PI / 2);
            g.translate(stepUp ? 1 : 0, 0);
        }
        else
        {
            float bounce = m.mode == Mode.CHAT ? -(float) Math.abs(Math.sin(clock * 9)) * 3 : (stepUp ? -1 : 0);
            float s = m.squash;
            g.translate(0, bounce);
            // the sprite faces left; flip it when heading right
            g.scale((1 - s * 0.22f) * (m.dir == 1 ? -1 : 1), 1 + s * 0.28f);
        }
        // feet on the origin: the sprite's body is centred 21px in and stands on its bottom row
        g.drawImage(img, -ImpSprite.WIDTH / 2, -ImpSprite.HEIGHT + 1, null);
        g.setTransform(old);

        if (m.rare && m.sparkAge < 0.9f)
        {
            float k = m.sparkAge / 0.9f;
            float a = (float) Math.sin(Math.PI * k);
            float r = 1.5f + 3f * a;
            float sx = x + m.sparkX;
            float sy = y + m.sparkY;
            g.setColor(new Color(255, 240, 150, Math.round(230 * a)));
            java.awt.geom.Path2D.Float star = new java.awt.geom.Path2D.Float();
            star.moveTo(sx, sy - r);
            star.lineTo(sx + r * 0.3f, sy - r * 0.3f);
            star.lineTo(sx + r, sy);
            star.lineTo(sx + r * 0.3f, sy + r * 0.3f);
            star.lineTo(sx, sy + r);
            star.lineTo(sx - r * 0.3f, sy + r * 0.3f);
            star.lineTo(sx - r, sy);
            star.lineTo(sx - r * 0.3f, sy - r * 0.3f);
            star.closePath();
            g.fill(star);
        }
        if (!m.bubble.isEmpty()) paintBubble(g, m.bubble, Math.round(x), Math.round(y) - 26);
    }

    private static final String[] HEART = {".x.x.", "xxxxx", "xxxxx", ".xxx.", "..x.."};
    private static final String[] NOTE = {"..xx.", "..x.x", "..x..", "xxx..", "xxx.."};
    private static final String[] DOTS = {".....", ".....", ".....", ".....", "x.x.x"};
    private static final String[] BANG = {"..x..", "..x..", "..x..", ".....", "..x.."};

    /** A tiny pixel symbol over an imp's head, with a dark edge so it reads on any card. */
    private static void paintBubble(Graphics2D g, String what, int cx, int top)
    {
        String[] rows = "heart".equals(what) ? HEART : "note".equals(what) ? NOTE : "!".equals(what) ? BANG : DOTS;
        Color c = "heart".equals(what) ? new Color(0xff7f9d) : new Color(0xffe9a8);
        for (int pass = 0; pass < 2; pass++)
        {
            g.setColor(pass == 0 ? new Color(0, 0, 0, 200) : c);
            for (int j = 0; j < rows.length; j++)
            {
                for (int i = 0; i < rows[j].length(); i++)
                {
                    if (rows[j].charAt(i) != 'x') continue;
                    int px = cx - 5 + i * 2;
                    int py = top + j * 2;
                    if (pass == 0) g.fillRect(px - 1, py - 1, 4, 4);
                    else g.fillRect(px, py, 2, 2);
                }
            }
        }
    }
}

package com.forgebingo;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LinearGradientPaint;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.font.TextAttribute;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import java.io.InputStream;
import java.util.Collections;
import java.util.function.DoubleConsumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.Timer;
import net.runelite.client.ui.ColorScheme;

/**
 * The side panel's look: the website's stone-and-gold palette, its Cinzel heading font, and the small painted
 * parts (cards, buttons, bars, board squares) with their gentle animations. Everything here is Swing-only and
 * runs on the EDT. Animations are short and stop by themselves; {@link #animations} turns them all off.
 */
final class PanelUi
{
    private PanelUi()
    {
    }

    // ---- palette (warm stone and soft gold, like the website's panels; easy on the eyes next to the game)
    static final Color BG = ColorScheme.DARK_GRAY_COLOR;
    static final Color CARD_TOP = new Color(0x363029);
    static final Color CARD_BOTTOM = new Color(0x2b2722);
    static final Color CARD_EDGE = new Color(0x4d4437);
    static final Color INSET = new Color(0x1f1c18);
    static final Color INSET_EDGE = new Color(0x3d362c);
    static final Color GOLD = new Color(0xffbf1f);
    static final Color GOLD_SOFT = new Color(0xe9b84e);
    static final Color GOLD_DARK = new Color(0xa07222);
    static final Color ORANGE = new Color(0xff981f);
    static final Color TEXT = new Color(0xe6dfd3);
    static final Color MUTED = new Color(0xa69d8f);
    static final Color GREEN = new Color(0x66d966);
    static final Color GREEN_DARK = new Color(0x2f6a33);
    static final Color AMBER = new Color(0xf2bb45);
    static final Color RED = new Color(0xff7b70);

    /** false = no motion at all: values jump, nothing pulses (the "Side panel animations" setting) */
    static volatile boolean animations = true;

    // ---- fonts
    private static final Font CINZEL = loadCinzel();
    private static final String SANS = pickSans();
    static final Font CLEAN_SMALL = new Font(SANS, Font.PLAIN, 11);
    static final Font CLEAN_BODY = new Font(SANS, Font.PLAIN, 12);
    static final Font CLEAN_BOLD = new Font(SANS, Font.BOLD, 13);
    /** headings: Cinzel, the website's display font (falls back to the bold body font if it cannot load) */
    static final Font CLEAN_HEAD = CINZEL == null ? CLEAN_BOLD : CINZEL.deriveFont(13f);
    static final Font CLEAN_TITLE = CINZEL == null ? CLEAN_BOLD.deriveFont(15f) : CINZEL.deriveFont(16f);
    static final Font CLEAN_CAPS = (CINZEL == null ? CLEAN_SMALL.deriveFont(Font.BOLD) : CINZEL.deriveFont(10.5f))
        .deriveFont(Collections.singletonMap(TextAttribute.TRACKING, 0.08f));

    private static Font loadCinzel()
    {
        try (InputStream in = PanelUi.class.getResourceAsStream("fonts/Cinzel-Bold.ttf"))
        {
            if (in == null) return null;
            Font f = Font.createFont(Font.TRUETYPE_FONT, in);
            // labels that wrap their text (HTML) look fonts up by family name, so the font has to be registered
            java.awt.GraphicsEnvironment.getLocalGraphicsEnvironment().registerFont(f);
            return f;
        }
        catch (Exception | LinkageError e)
        {
            return null;
        }
    }

    /** A smooth system sans-serif where there is one; Java's own otherwise. */
    private static String pickSans()
    {
        try
        {
            java.util.Set<String> have = new java.util.HashSet<>(java.util.Arrays.asList(
                java.awt.GraphicsEnvironment.getLocalGraphicsEnvironment().getAvailableFontFamilyNames()));
            for (String f : new String[] {"Segoe UI", "Inter", "SF Pro Text", "Helvetica Neue", "Noto Sans", "DejaVu Sans"})
            {
                if (have.contains(f)) return f;
            }
        }
        catch (RuntimeException | LinkageError e)
        {
            // fall through
        }
        return Font.SANS_SERIF;
    }

    /** The heading font when it has every character of the text (it is Latin only); the fallback otherwise. */
    static Font headingFor(String text, Font heading, Font fallback)
    {
        return text == null || heading.canDisplayUpTo(text) < 0 ? heading : fallback;
    }

    static Graphics2D smooth(Graphics g)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
        return g2;
    }

    static Color mix(Color a, Color b, float t)
    {
        float k = Math.max(0f, Math.min(1f, t));
        return new Color(
            Math.round(a.getRed() + (b.getRed() - a.getRed()) * k),
            Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * k),
            Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * k),
            Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * k));
    }

    static Color alpha(Color c, int a)
    {
        return new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.max(0, Math.min(255, a)));
    }

    /** A slow breath between 0 and 1 (about 2.6 s), shared so everything that glows glows together. */
    static float pulse()
    {
        if (!animations) return 1f;
        return 0.5f + 0.5f * (float) Math.sin(System.currentTimeMillis() / 2600.0 * Math.PI * 2);
    }

    /** Runs f with an eased 0..1 over ms milliseconds (or just once with 1 when animations are off). */
    static void tween(int ms, DoubleConsumer f)
    {
        if (!animations)
        {
            f.accept(1);
            return;
        }
        long start = System.nanoTime();
        Timer t = new Timer(16, null);
        t.addActionListener(e -> {
            double k = Math.min(1.0, (System.nanoTime() - start) / 1e6 / ms);
            f.accept(1 - Math.pow(1 - k, 3));
            if (k >= 1) t.stop();
        });
        f.accept(0);
        t.start();
    }

    /** A value that glides between 0 and 1 (hover highlights). */
    static final class Fader
    {
        private final JComponent owner;
        private final int ms;
        private final Timer timer = new Timer(16, e -> step());
        private float value;
        private float target;
        private long last;

        Fader(JComponent owner, int ms)
        {
            this.owner = owner;
            this.ms = ms;
        }

        void set(boolean on)
        {
            target = on ? 1f : 0f;
            if (!animations)
            {
                value = target;
                owner.repaint();
                return;
            }
            if (!timer.isRunning())
            {
                last = System.nanoTime();
                timer.start();
            }
        }

        float get()
        {
            return value;
        }

        private void step()
        {
            long now = System.nanoTime();
            float d = (now - last) / 1e6f / ms;
            last = now;
            value = target > value ? Math.min(target, value + d) : Math.max(target, value - d);
            if (value == target || !owner.isDisplayable()) timer.stop();
            owner.repaint();
        }
    }

    // ------------------------------------------------------------------ card

    /** A rounded stone card: soft gradient, thin edge, optional coloured stripe down the left. */
    static class Card extends JPanel
    {
        private static final int ARC = 8;
        private Color accent;
        private Color edge = CARD_EDGE;
        private boolean inset;
        private Fader hover;
        private float alpha = 1f;
        private float lift;

        Card(Color accent)
        {
            this.accent = accent;
            setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
            setOpaque(false);
            setAlignmentX(LEFT_ALIGNMENT);
            pad(8, 8, 8, 8);
            putClientProperty(PanelImps.PLATFORM, Boolean.TRUE);
        }

        /** Padding inside the card; the stripe's width is added on the left. */
        final Card pad(int top, int left, int bottom, int right)
        {
            setBorder(BorderFactory.createEmptyBorder(top, left + (accent == null ? 0 : 3), bottom, right));
            return this;
        }

        /** The darker, sunken look (a task inside a tile card). */
        Card inset(Color edgeColour)
        {
            inset = true;
            edge = edgeColour == null ? INSET_EDGE : edgeColour;
            return this;
        }

        /** Brightens a little under the mouse. */
        Card hoverable()
        {
            hover = new Fader(this, 130);
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            addMouseListener(new MouseAdapter()
            {
                @Override
                public void mouseEntered(MouseEvent e)
                {
                    hover.set(true);
                }

                @Override
                public void mouseExited(MouseEvent e)
                {
                    hover.set(false);
                }
            });
            return this;
        }

        /** Fades in and settles up a few pixels (a tile being opened, team news arriving). */
        void fadeIn()
        {
            tween(240, k -> {
                alpha = (float) k;
                lift = (float) (1 - k) * 5f;
                repaint();
            });
        }

        @Override
        public void paint(Graphics g)
        {
            if (alpha >= 1f && lift <= 0f)
            {
                super.paint(g);
                return;
            }
            Graphics2D g2 = (Graphics2D) g.create();
            try
            {
                g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.max(0f, Math.min(1f, alpha))));
                g2.translate(0, Math.round(lift));
                super.paint(g2);
            }
            finally
            {
                g2.dispose();
            }
        }

        @Override
        protected void paintComponent(Graphics g)
        {
            int w = getWidth();
            int h = getHeight();
            Graphics2D g2 = smooth(g);
            try
            {
                float hv = hover == null ? 0f : hover.get();
                Shape body = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1f, h - 1f, ARC, ARC);
                if (inset)
                {
                    g2.setColor(INSET);
                }
                else
                {
                    Color top = mix(CARD_TOP, new Color(0x4a4135), hv);
                    Color bottom = mix(CARD_BOTTOM, new Color(0x3a332a), hv);
                    g2.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
                }
                g2.fill(body);
                if (accent != null)
                {
                    Shape old = g2.getClip();
                    g2.clip(body);
                    g2.setColor(accent);
                    g2.fillRect(0, 0, 3, h);
                    g2.setClip(old);
                }
                if (!inset)
                {
                    // a faint light line under the top edge, like the bevel on the website's panels
                    g2.setColor(new Color(255, 240, 210, 16));
                    g2.drawLine(ARC / 2 + 1, 1, w - ARC / 2 - 2, 1);
                }
                g2.setColor(mix(edge, GOLD_DARK, hv * 0.7f));
                g2.draw(body);
            }
            finally
            {
                g2.dispose();
            }
        }
    }

    // ------------------------------------------------------------------ button

    /** A stone button with a gold edge that warms up under the mouse. */
    static final class StoneButton extends JButton
    {
        private final Fader hover = new Fader(this, 120);

        StoneButton(String text)
        {
            super(text);
            setContentAreaFilled(false);
            setBorderPainted(false);
            setFocusPainted(false);
            setFocusable(false);
            setOpaque(false);
            setRolloverEnabled(false);
            setForeground(TEXT);
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            setBorder(BorderFactory.createEmptyBorder(3, 8, 3, 8));
            putClientProperty(PanelImps.PLATFORM, Boolean.TRUE);
            addMouseListener(new MouseAdapter()
            {
                @Override
                public void mouseEntered(MouseEvent e)
                {
                    hover.set(true);
                }

                @Override
                public void mouseExited(MouseEvent e)
                {
                    hover.set(false);
                }
            });
        }

        @Override
        protected void paintComponent(Graphics g)
        {
            int w = getWidth();
            int h = getHeight();
            Graphics2D g2 = smooth(g);
            try
            {
                boolean down = getModel().isArmed() && getModel().isPressed();
                float hv = isEnabled() ? hover.get() : 0f;
                Shape body = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1f, h - 1f, 7, 7);
                Color top = down ? new Color(0x2a251f) : mix(new Color(0x453c30), new Color(0x54483a), hv);
                Color bottom = down ? new Color(0x332d25) : mix(new Color(0x322c25), new Color(0x3d352c), hv);
                g2.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
                g2.fill(body);
                if (!down)
                {
                    g2.setColor(new Color(255, 240, 210, 20));
                    g2.drawLine(4, 1, w - 5, 1);
                }
                g2.setColor(mix(new Color(0x6a5e50), GOLD, hv * 0.75f));
                g2.draw(body);

                g2.setFont(getFont());
                FontMetrics fm = g2.getFontMetrics();
                String text = getText() == null ? "" : getText();
                int x = (w - fm.stringWidth(text)) / 2;
                int y = (h - fm.getHeight()) / 2 + fm.getAscent() + (down ? 1 : 0);
                g2.setColor(new Color(0, 0, 0, 150));
                g2.drawString(text, x + 1, y + 1);
                Color fg = isEnabled() ? getForeground() : MUTED;
                g2.setColor(mix(fg, new Color(0xffd83d), hv * 0.6f));
                g2.drawString(text, x, y);
            }
            finally
            {
                g2.dispose();
            }
        }
    }

    // ------------------------------------------------------------------ progress bar

    /** A rounded gold bar whose fill glides to its new value with one soft sheen. */
    static final class GoldBar extends JComponent
    {
        private int max = 1;
        private int value;
        private double shown;
        private double sheen = -1;
        private String text;
        private boolean first = true;
        private int run;

        GoldBar()
        {
            setOpaque(false);
            setForeground(GOLD);
            putClientProperty(PanelImps.PLATFORM, Boolean.TRUE);
        }

        void setMaximum(int m)
        {
            max = Math.max(1, m);
        }

        void setString(String s)
        {
            text = s;
            repaint();
        }

        /** Jumps there (a redraw of something already on screen). */
        void setValueNow(int v)
        {
            run++;
            value = Math.max(0, Math.min(max, v));
            shown = value;
            sheen = -1;
            first = false;
            repaint();
        }

        /** Glides there from where the bar is now (from empty the first time). */
        void setValue(int v)
        {
            int to = Math.max(0, Math.min(max, v));
            if (to == value && !first) return;
            first = false;
            value = to;
            double from = Math.min(shown, max);
            int mine = ++run;
            tween(520, k -> {
                if (mine != run) return;
                shown = from + (to - from) * k;
                sheen = k < 1 ? k : -1;
                repaint();
            });
        }

        @Override
        protected void paintComponent(Graphics g)
        {
            int w = getWidth();
            int h = getHeight();
            Graphics2D g2 = smooth(g);
            try
            {
                float arc = Math.min(h, 8);
                Shape track = new RoundRectangle2D.Float(0, 0, w, h, arc, arc);
                g2.setColor(new Color(0x14110e));
                g2.fill(track);
                int fw = (int) Math.round(w * Math.max(0, Math.min(1, shown / max)));
                if (fw > 0)
                {
                    Shape old = g2.getClip();
                    g2.clip(track);
                    Color c = getForeground();
                    g2.setPaint(new GradientPaint(0, 0, mix(c, Color.WHITE, 0.22f), 0, h, mix(c, Color.BLACK, 0.28f)));
                    g2.fillRect(0, 0, fw, h);
                    if (sheen >= 0)
                    {
                        float sx = (float) (-20 + (fw + 40) * sheen);
                        int a = (int) (70 * Math.sin(Math.PI * sheen));
                        g2.clipRect(0, 0, fw, h);
                        g2.setPaint(new LinearGradientPaint(sx - 14, 0, sx + 14, 0, new float[] {0f, 0.5f, 1f},
                            new Color[] {new Color(255, 255, 255, 0), new Color(255, 255, 255, Math.max(0, a)), new Color(255, 255, 255, 0)}));
                        g2.fillRect((int) sx - 14, 0, 28, h);
                    }
                    g2.setClip(old);
                }
                g2.setColor(new Color(0, 0, 0, 110));
                g2.draw(new RoundRectangle2D.Float(0.5f, 0.5f, w - 1f, h - 1f, arc, arc));
                if (text != null && !text.isEmpty() && h >= 12)
                {
                    g2.setFont(getFont());
                    FontMetrics fm = g2.getFontMetrics();
                    int x = (w - fm.stringWidth(text)) / 2;
                    int y = (h - fm.getHeight()) / 2 + fm.getAscent();
                    g2.setColor(new Color(0, 0, 0, 190));
                    g2.drawString(text, x + 1, y + 1);
                    g2.setColor(new Color(0xfff6e2));
                    g2.drawString(text, x, y);
                }
            }
            finally
            {
                g2.dispose();
            }
        }
    }

    // ------------------------------------------------------------------ board square

    /** One square of the mini board: rounded, lit from above, gold ring when open, a soft lift under the mouse. */
    static final class TileCell extends JLabel
    {
        private final Fader hover = new Fader(this, 110);
        private boolean selected;
        private boolean interactive;

        TileCell()
        {
            setOpaque(false);
            setHorizontalAlignment(CENTER);
        }

        void makeInteractive()
        {
            interactive = true;
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            addMouseListener(new MouseAdapter()
            {
                @Override
                public void mouseEntered(MouseEvent e)
                {
                    hover.set(true);
                }

                @Override
                public void mouseExited(MouseEvent e)
                {
                    hover.set(false);
                }
            });
        }

        void setSelected(boolean on)
        {
            if (selected == on) return;
            selected = on;
            repaint();
        }

        boolean isSelected()
        {
            return selected;
        }

        @Override
        protected void paintComponent(Graphics g)
        {
            int w = getWidth();
            int h = getHeight();
            Graphics2D g2 = smooth(g);
            try
            {
                float arc = Math.max(3f, Math.min(6f, w / 5f));
                Shape body = new RoundRectangle2D.Float(1f, 1f, w - 2f, h - 2f, arc, arc);
                Color bg = getBackground();
                float hv = interactive ? hover.get() : 0f;
                g2.setPaint(new GradientPaint(0, 0, mix(bg, Color.WHITE, 0.10f + 0.10f * hv), 0, h, mix(bg, Color.BLACK, 0.12f)));
                g2.fill(body);
                g2.setColor(new Color(0, 0, 0, 120));
                g2.draw(new RoundRectangle2D.Float(1.5f, 1.5f, w - 3f, h - 3f, arc, arc));
                if (selected)
                {
                    float p = pulse();
                    g2.setStroke(new BasicStroke(3f));
                    g2.setColor(alpha(GOLD, Math.round(40 + 55 * p)));
                    g2.draw(new RoundRectangle2D.Float(1.5f, 1.5f, w - 3f, h - 3f, arc, arc));
                    g2.setStroke(new BasicStroke(1.4f));
                    g2.setColor(GOLD);
                    g2.draw(new RoundRectangle2D.Float(1f, 1f, w - 2f, h - 2f, arc, arc));
                }
                else if (hv > 0f)
                {
                    g2.setStroke(new BasicStroke(1.2f));
                    g2.setColor(alpha(GOLD_SOFT, Math.round(190 * hv)));
                    g2.draw(new RoundRectangle2D.Float(1f, 1f, w - 2f, h - 2f, arc, arc));
                }
            }
            finally
            {
                g2.dispose();
            }
            super.paintComponent(g);
        }
    }

