        return ids;
    }

    private static Pet pet(String name, int[] items, int[] npcs, String... sources)
    {
        List<String> s = new ArrayList<>();
        Collections.addAll(s, sources);
        return new Pet(name, items, npcs, Collections.unmodifiableList(s));
    }

