package com.forgebingo.core;

import java.util.List;
import java.util.Random;
import java.util.function.LongSupplier;
import java.util.function.Function;

/**
 * Drains the {@link OfflineQueue}. Not thread-safe by itself: call {@link #drain()}
 * from one executor thread at a time (the plugin synchronizes on the instance).
 */
public final class QueueProcessor
{
    /** Receives everything the user should know about. */
    public interface Listener
    {
        /** Server accepted the event (also fires for duplicates). */
        void onAccepted(GameEvent event, ApiModels.EventResult result);

        /** Event permanently dropped; show a notice. */
        void onDropped(GameEvent event, String reason);

        /** Key rejected; sending is paused until the key changes or user retries. */
        void onAuthProblem(String message);

        /** Queue state changed (size). */
        void onQueueChanged(int size, String lastError);
    }

    private final OfflineQueue queue;
    private final Function<GameEvent, ApiResult<ApiModels.EventResult>> sender;
    private final Listener listener;
    private final LongSupplier clock;
    private final Random random;
    private volatile boolean authPaused;

    public QueueProcessor(OfflineQueue queue, Function<GameEvent, ApiResult<ApiModels.EventResult>> sender,
        Listener listener, LongSupplier clock, Random random)
    {
        this.queue = queue;
        this.sender = sender;
        this.listener = listener;
        this.clock = clock;
        this.random = random;
    }

    public void resumeAfterAuthChange()
    {
        authPaused = false;
        queue.retryAllNow(clock.getAsLong());
    }

    public boolean isAuthPaused()
    {
        return authPaused;
    }

    /** @return millis until the next entry becomes due, or -1 when the queue is empty. */
    public synchronized long drain()
    {
        long now = clock.getAsLong();
        for (QueuedEvent expired : queue.expire(now))
        {
            listener.onDropped(expired.event, "too old to be accepted (over 23 hours offline)");
        }
        if (authPaused)
        {
            return queue.size() == 0 ? -1 : 60_000L;
        }
        String lastError = null;
        for (QueuedEvent q : queue.due(now))
        {
            ApiResult<ApiModels.EventResult> r = sender.apply(q.event);
            ErrorClass c = r.errorClass();
            if (c == ErrorClass.SUCCESS)
            {
                queue.remove(q.event.id);
                listener.onAccepted(q.event, r.body);
            }
            else if (c == ErrorClass.PERMANENT)
            {
                queue.remove(q.event.id);
                listener.onDropped(q.event, r.describe());
            }
            else if (c == ErrorClass.CONFLICT)
            {
                // event_id_conflict: the id belongs to someone else (never happens with UUIDv4). New id, retry soon.
                queue.remove(q.event.id);
                q.event.id = java.util.UUID.randomUUID().toString();
                q.nextAttemptAtMillis = clock.getAsLong();
                queue.add(q);
            }
            else if (c == ErrorClass.AUTH)
            {
                authPaused = true;
                lastError = r.describe();
                listener.onAuthProblem(ConnectionStatus.authMessage(r.errorCode));
                break;
            }
            else
            {
                int attempts = q.attempts + 1;
                long delay = Backoff.delayMillis(attempts, r.retryAfterMillis, random);
                queue.scheduleRetry(q.event.id, attempts, clock.getAsLong() + delay, r.describe());
                lastError = r.describe();
                if (r.status == 429 || r.status == 0)
                {
                    break; // do not hammer: the rest would likely fail the same way
                }
            }
        }
        listener.onQueueChanged(queue.size(), lastError);
        return nextDelay();
    }

    private long nextDelay()
    {
        long now = clock.getAsLong();
        long min = Long.MAX_VALUE;
        List<QueuedEvent> all = queue.due(Long.MAX_VALUE);
        for (QueuedEvent q : all)
        {
            min = Math.min(min, q.nextAttemptAtMillis);
        }
        return all.isEmpty() ? -1 : Math.max(1_000L, min - now);
    }
}

package com.forgebingo.core;

/** A {@link GameEvent} waiting to be delivered, plus its retry state. */
public final class QueuedEvent
{
    public GameEvent event;
    public int attempts;
    public long createdAtMillis;
    public long nextAttemptAtMillis;
    public String lastError;

    public QueuedEvent()
    {
    }

    public QueuedEvent(GameEvent event, long now)
    {
        this.event = event;
        this.createdAtMillis = now;
        this.nextAttemptAtMillis = now;
    }
}

package com.forgebingo.core;

import java.util.ArrayList;
import java.util.List;

/** Size caps and defensive cleanup for outgoing events and incoming server data. */
public final class Sanitizer
{
    public static final int MAX_STRING = 200;
    public static final int MAX_ITEMS_PER_EVENT = 40;
    public static final int MAX_EVENT_JSON_BYTES = 16 * 1024;
    public static final int MAX_EVENTS = 100;
    public static final int MAX_TILES = 400;
    public static final int MAX_TASKS = 50;

    private Sanitizer()
    {
    }

    public static String str(String s)
    {
        if (s == null)
        {
            return null;
        }
        StringBuilder sb = new StringBuilder(Math.min(s.length(), MAX_STRING));
        for (int i = 0; i < s.length() && sb.length() < MAX_STRING; i++)
        {
            char c = s.charAt(i);
            sb.append(Character.isISOControl(c) ? ' ' : c);
        }
        return sb.toString();
    }

    private static final java.util.regex.Pattern RSN = java.util.regex.Pattern.compile("^[A-Za-z0-9 _-]{1,12}$");

    /** RuneScape names use non-breaking spaces in some client APIs; the server wants plain spaces. */
    public static String normalizeRsn(String rsn)
    {
        return rsn == null ? null : str(rsn.replace('\u00a0', ' ')).trim();
    }

    /** Same pattern as the server (^[A-Za-z0-9 _-]{1,12}$): events that fail it are never sent. */
    public static boolean validRsn(String rsn)
    {
        return rsn != null && RSN.matcher(rsn).matches();
    }

    /** Trims strings and item lists of an outgoing event in place. */
    public static void event(GameEvent e)
    {
        e.sourceName = str(e.sourceName);
        e.npcName = str(e.npcName);
        e.skill = str(e.skill);
        e.rsn = normalizeRsn(e.rsn);
        if (e.items != null)
        {
            if (e.items.size() > MAX_ITEMS_PER_EVENT)
            {
                e.items = new ArrayList<>(e.items.subList(0, MAX_ITEMS_PER_EVENT));
            }
            for (GameEvent.Item i : e.items)
            {
                if (i.quantity < 1)
                {
                    i.quantity = 1;
                }
            }
        }
    }

    private static <T> List<T> cap(List<T> in, int max)
    {
        if (in == null)
        {
            return new ArrayList<>();
        }
        return in.size() <= max ? in : new ArrayList<>(in.subList(0, max));
    }

    /** Item ids: at most max, positive, below 1,000,000; null in, empty out. */
    private static List<Integer> cleanIds(List<Integer> in, int max)
    {
        List<Integer> out = new ArrayList<>();
        if (in == null) return out;
        for (Integer i : in)
        {
            if (i != null && i > 0 && i < 1_000_000 && out.size() < max) out.add(i);
        }
        return out;
    }

    private static int clamp(int v)
    {
        return Math.max(0, Math.min(v, 1_000_000_000));
    }

    public static ApiModels.BoardsResponse boards(ApiModels.BoardsResponse r)
    {
        if (r == null)
        {
            return null;
        }
        r.boards = cap(r.boards, MAX_EVENTS);
        r.boards.removeIf(b -> b == null || b.teamBoardId == null || b.teamBoardId.length() > 64);
        for (ApiModels.BoardSummary b : r.boards)
        {
            b.eventName = str(b.eventName);
            b.boardTitle = str(b.boardTitle);
            b.teamName = str(b.teamName);
            b.role = str(b.role);
            b.status = str(b.status);
            b.boardSize = Math.max(1, Math.min(b.boardSize, 20));
            b.completedCount = clamp(b.completedCount);
            b.totalTiles = clamp(b.totalTiles);
        }
        return r;
    }

    public static ApiModels.BoardResponse board(ApiModels.BoardResponse b)
    {
        if (b == null)
        {
            return null;
        }
        if (b.board == null)
        {
            b.board = new ApiModels.BoardInfo();
            b.board.size = 1;
        }
        b.board.size = Math.max(1, Math.min(b.board.size, 20));
        b.board.title = str(b.board.title);
        b.teamName = str(b.teamName);
        if (b.event != null)
        {
            String kw = str(b.event.keyword);
            b.event.keyword = kw == null ? null : kw.trim().substring(0, Math.min(kw.trim().length(), 40));
        }
        b.tiles = cap(b.tiles, MAX_TILES);
        b.tiles.removeIf(t -> t == null);
        b.hiddenItemIds = cap(b.hiddenItemIds, 500);
        b.hiddenItemIds.removeIf(i -> i == null || i < 0);
        for (ApiModels.Tile t : b.tiles)
        {
            t.title = str(t.title);
            t.description = str(t.description);
            t.points = clamp(t.points);
            t.row = Math.max(0, Math.min(t.row, 19));
            t.col = Math.max(0, Math.min(t.col, 19));
            if (t.iconUrl != null && !IconRef.isProxyPath(t.iconUrl))
            {
                t.iconUrl = null;
            }
            // only ever compared against TileIcons' table, never drawn as text or used in a URL
            if (t.iconEmoji != null && (t.iconEmoji.isEmpty() || t.iconEmoji.length() > 16)) t.iconEmoji = null;
            t.tasks = cap(t.tasks, MAX_TASKS);
            t.tasks.removeIf(x -> x == null);
            for (ApiModels.Task k : t.tasks)
            {
                k.description = str(k.description);
                k.rejectedReason = k.rejectedReason == null ? null : str(k.rejectedReason);
                if (k.points != null) k.points = Math.max(0, Math.min(1000, k.points));
                k.requiredQty = clamp(k.requiredQty);
                k.approvedQty = clamp(k.approvedQty);
                k.pendingQty = clamp(k.pendingQty);
                // item ids drive the per-item list, the icon fallback and the screenshot pre-check; npc ids are not needed
                k.itemIds = cleanIds(k.itemIds, 200);
                k.npcIds = null;
                if (k.itemGroups != null)
                {
                    k.itemGroups = cap(k.itemGroups, 20);
                    k.itemGroups.replaceAll(g -> cleanIds(g, 50));
                }
                if (k.itemProgress != null)
                {
                    if (k.itemProgress.size() > 220) k.itemProgress = null;
                    else
                    {
                        k.itemProgress.entrySet().removeIf(e -> e.getKey() == null || !e.getKey().matches("[ig]\\d{1,6}") || e.getValue() == null);
                        for (ApiModels.SlotProgress p : k.itemProgress.values())
                        {
                            p.approved = clamp(p.approved);
                            p.pending = clamp(p.pending);
                        }
                    }
                }
            }
            if (t.workingOn != null)
            {
                t.workingOn = cap(t.workingOn, 30);
                t.workingOn.removeIf(w -> w == null || w.name == null);
                for (ApiModels.WorkingOn w : t.workingOn) w.name = str(w.name).length() > 32 ? str(w.name).substring(0, 32) : str(w.name);
            }
        }
        if (b.event != null)
        {
            b.event.name = str(b.event.name);
        }
        return b;
    }

    public static ApiModels.LeaderboardResponse leaderboard(ApiModels.LeaderboardResponse r)
    {
        if (r == null)
        {
            return null;
        }
        r.teams = cap(r.teams, 200);
        r.teams.removeIf(t -> t == null);
        for (ApiModels.LeaderboardTeam t : r.teams)
        {
            t.teamName = str(t.teamName);
            t.score = clamp(t.score);
        }
        return r;
    }

    public static ApiModels.EventResult result(ApiModels.EventResult r)
    {
        if (r == null)
        {
            return null;
        }
        r.matched = cap(r.matched, 100);
        r.matched.removeIf(m -> m == null);
        r.matchedTiles = cap(r.matchedTiles, 100);
        r.skipped = cap(r.skipped, 100);
        r.skipped.removeIf(x -> x == null);
        for (ApiModels.Skipped x : r.skipped)
        {
            x.reason = str(x.reason);
        }
        return r;
    }

    public static ApiModels.Me me(ApiModels.Me m)
    {
        if (m != null)
        {
            m.displayName = str(m.displayName);
            m.keyScope = str(m.keyScope);
        }
        return m;
    }

    public static ApiModels.HelloResponse hello(ApiModels.HelloResponse r)
    {
        if (r == null)
        {
            return null;
        }
        r.displayName = str(r.displayName);
        r.rsn = str(r.rsn);
        r.keyScope = str(r.keyScope);
        r.memberships = cap(r.memberships, 20);
        r.memberships.removeIf(x -> x == null);
        for (ApiModels.Membership m : r.memberships)
        {
            m.eventName = str(m.eventName);
            m.teamName = str(m.teamName);
            m.joinedRsn = str(m.joinedRsn);
            m.pluginRsn = str(m.pluginRsn);
            m.status = str(m.status);
            m.eventStatus = str(m.eventStatus);
        }
        return r;
    }

    public static final int MAX_CATALOGUE_ITEMS = 20_000;

    public static ApiModels.CatalogueResponse catalogue(ApiModels.CatalogueResponse r)
    {
        if (r == null)
        {
            return null;
        }
        r.items = cap(r.items, MAX_CATALOGUE_ITEMS);
        r.items.removeIf(i -> i == null || i.id < 0 || i.name == null || i.name.isEmpty());
        for (ApiModels.CatalogueItem i : r.items)
        {
            i.name = str(i.name);
        }
        return r;
    }
}

package com.forgebingo.core;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.Iterator;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.stream.ImageOutputStream;

/**
 * Screenshots go up as JPEG: a full game window as PNG is several MB and timed out on ordinary home upload speeds
 * (owner report 2026-11-12, "SocketTimeoutException"). JPEG at 85% is roughly a tenth of that and still reads fine
 * for proof. Falls back to lower quality if a shot is still over the limit.
 */
public final class ScreenshotEncode
{
    private ScreenshotEncode()
    {
    }

    /** JPEG bytes no bigger than maxBytes (tries 85%, 70%, 55%), or null if the image cannot be encoded. */
    public static byte[] jpeg(BufferedImage img, int maxBytes) throws IOException
    {
        BufferedImage rgb = new BufferedImage(img.getWidth(), img.getHeight(), BufferedImage.TYPE_INT_RGB);
        Graphics2D g = rgb.createGraphics();
        try
        {
            g.setColor(Color.BLACK); // JPEG has no transparency
            g.fillRect(0, 0, rgb.getWidth(), rgb.getHeight());
            g.drawImage(img, 0, 0, null);
        }
        finally
        {
            g.dispose();
        }
        byte[] out = null;
        for (float q : new float[] {0.85f, 0.7f, 0.55f})
        {
            out = encode(rgb, q);
            if (out == null || out.length <= maxBytes) return out;
        }
        return out;
    }

    private static byte[] encode(BufferedImage rgb, float quality) throws IOException
    {
        Iterator<ImageWriter> it = ImageIO.getImageWritersByFormatName("jpeg");
        if (!it.hasNext()) return null;
        ImageWriter w = it.next();
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (ImageOutputStream ios = ImageIO.createImageOutputStream(bytes))
        {
            w.setOutput(ios);
            ImageWriteParam p = w.getDefaultWriteParam();
            p.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
            p.setCompressionQuality(quality);
            w.write(null, new IIOImage(rgb, null, null), p);
        }
        finally
        {
            w.dispose();
        }
        return bytes.toByteArray();
    }

    /** True when the bytes are a JPEG (FF D8 FF), else they are treated as PNG. */
    public static boolean isJpeg(byte[] b)
    {
        return b != null && b.length > 3 && (b[0] & 0xff) == 0xff && (b[1] & 0xff) == 0xd8 && (b[2] & 0xff) == 0xff;
    }
}

package com.forgebingo.core;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;

/** Stamps the event keyword and the local date/time in the top-left corner of a proof screenshot copy. */
public final class ScreenshotStamp
{
    private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
    private static final DateTimeFormatter OFFSET = DateTimeFormatter.ofPattern("xxx");

    private ScreenshotStamp()
    {
    }

    /** "yyyy-MM-dd HH:mm +02:00" */
    public static String timeText(ZonedDateTime t)
    {
        return TIME.format(t) + " UTC" + OFFSET.format(t);
    }

    /** Returns a new image (same size) with the stamp drawn; the source is not modified. */
    public static BufferedImage stamp(BufferedImage src, String keyword, ZonedDateTime when)
    {
        return stamp(src, keyword, when, null, null);
    }

    /**
     * Proof stamp (owner, 2026-11-12): the tile it is for, the player, "Code: keyword" and the date/time, top-left.
     * Any of tile / player / keyword may be null or blank and is then left out.
     */
    public static BufferedImage stamp(BufferedImage src, String keyword, ZonedDateTime when, String player, String tile)
    {
        java.util.List<String> lines = new java.util.ArrayList<>();
        if (tile != null && !tile.trim().isEmpty()) lines.add(clip(tile.trim(), 48));
        if (player != null && !player.trim().isEmpty()) lines.add(clip(player.trim(), 24));
        if (keyword != null && !keyword.trim().isEmpty()) lines.add("Code: " + clip(keyword.trim(), 40));
        lines.add(timeText(when));
        return draw(src, lines.toArray(new String[0]));
    }

    private static String clip(String s, int max)
    {
        return s.length() <= max ? s : s.substring(0, max - 1) + "…";
    }

    private static BufferedImage draw(BufferedImage src, String[] lines)
    {
        BufferedImage out = new BufferedImage(src.getWidth(), src.getHeight(), BufferedImage.TYPE_INT_RGB);
        Graphics2D g = out.createGraphics();
        try
        {
            g.drawImage(src, 0, 0, null);
            int size = Math.max(14, Math.min(24, src.getHeight() / 40));
            g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, size));
            FontMetrics fm = g.getFontMetrics();
            int pad = Math.max(4, size / 3);
            int w = 0;
            for (String l : lines) w = Math.max(w, fm.stringWidth(l));
            int lineH = fm.getHeight();
            int boxW = Math.min(src.getWidth(), w + pad * 2);
            int boxH = Math.min(src.getHeight(), lineH * lines.length + pad * 2);
            g.setColor(new Color(0, 0, 0, 190));
            g.fillRect(0, 0, boxW, boxH);
            g.setColor(Color.WHITE);
            int y = pad + fm.getAscent();
            for (String l : lines)
            {
                g.drawString(l, pad, y);
                y += lineH;
            }
        }
        finally
        {
            g.dispose();
        }
        return out;
    }
}

package com.forgebingo.core;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Maps a LootReceived source name onto one of the server's source types and normalises clue names. */
public final class SourceClassifier
{
    private static final Pattern TIER = Pattern.compile("\\b(beginner|easy|medium|hard|elite|master)\\b");

    private SourceClassifier()
    {
    }

    /**
     * Loot that never counts (owner, 2026-11-11): Wilderness loot keys. Their chest just hands back items taken from
     * other players, so it is neither a drop nor a task. RuneLite's loot tracker names it "Loot Chest".
     */
    public static boolean ignored(String name)
    {
        String n = name == null ? "" : name.toLowerCase(Locale.ROOT).trim();
        return n.equals("loot chest") || n.contains("loot key");
    }

    public static String forEventLoot(String name)
    {
        String n = name == null ? "" : name.toLowerCase(Locale.ROOT);
        if (n.startsWith("reward casket") || n.contains("clue scroll") || n.contains("clue casket"))
        {
            return GameEvent.CLUE;
        }
        // Raids, Barrows and every other chest / minigame reward share one bucket;
        // the server matches sourceName against its catalogue (unknown names match nothing).
        return GameEvent.RAID_CHEST;
    }

    /** "Reward casket (elite)" -> "elite"; null when no tier is present. */
    public static String clueTier(String name)
    {
        if (name == null)
        {
            return null;
        }
        Matcher m = TIER.matcher(name.toLowerCase(Locale.ROOT));
        return m.find() ? m.group(1) : null;
    }
}

