        EMOJI.put("🏆", 9813);        // trophy
        EMOJI.put("🐲", 12653);       // dragon face
        EMOJI.put("📜", 2722);        // scroll
        EMOJI.put("🗺", 19835);       // map
        EMOJI.put("⬆", 13280);             // up arrow
        EMOJI.put("⛏", 1275);              // pick
