        EMOJI.put("📈", 2528);        // chart
        EMOJI.put("🧍", 11640);       // standing person
        EMOJI.put("🏃", 11850);       // runner
        EMOJI.put("🐾", 3695);        // paw prints
        EMOJI.put("🙇", 288);         // bowing
        EMOJI.put("⚰", 4716);              // coffin
        EMOJI.put("🎲", 6199);        // die
        EMOJI.put("👑", 21018);       // crown
        EMOJI.put("🔥", 6570);        // fire
        EMOJI.put("💰", 995);         // money bag
        EMOJI.put("🪙", 995);         // coin
    }

    private TileIcons()
    {
    }

    /** An item to draw for this tile when it has no item icon of its own, or null (show its initials). */
    public static Integer fallbackItem(ApiModels.Tile t)
    {
        if (t == null) return null;
        String title = t.title == null ? "" : " " + t.title.toLowerCase(Locale.ROOT) + " ";
        for (Map.Entry<String, Integer> e : TITLE.entrySet())
        {
            if (containsWord(title, e.getKey())) return e.getValue();
        }
        if (t.iconEmoji != null)
        {
            for (Map.Entry<String, Integer> e : EMOJI.entrySet())
            {
                if (t.iconEmoji.startsWith(e.getKey())) return e.getValue();
            }
        }
        if (t.tasks != null)
        {
            for (ApiModels.Task k : t.tasks)
            {
                if (k != null && k.itemIds != null && !k.itemIds.isEmpty() && k.itemIds.get(0) != null && k.itemIds.get(0) > 0)
                {
                    return k.itemIds.get(0);
                }
            }
        }
        return null;
    }

    /** Skill name (as the plugin reports it) -> that skill's cape, for level-up tasks. */
    private static final Map<String, Integer> SKILL = new LinkedHashMap<>();

    static
    {
        String[] names = {"attack", "strength", "defence", "ranged", "prayer", "magic", "runecraft", "hitpoints", "agility", "herblore",
            "thieving", "crafting", "fletching", "slayer", "construction", "mining", "smithing", "fishing", "cooking", "firemaking",
            "woodcutting", "farming"};
        int[] capes = {9747, 9750, 9753, 9756, 9759, 9762, 9765, 9768, 9771, 9774, 9777, 9780, 9783, 9786, 9789, 9792, 9795, 9798,
            9801, 9804, 9807, 9810};
        for (int i = 0; i < names.length; i++) SKILL.put(names[i], capes[i]);
        SKILL.put("hunter", 9948);
        SKILL.put("sailing", 13280);
        SKILL.put("overall", 13280);            // Max cape
    }

    /**
     * The picture for one task: its own item, else its skill's cape (level-ups), else a boss/activity named in its
     * text, else the tile's picture. Null only when nothing at all fits (the panel then draws a tick box).
     */
    public static Integer taskItem(ApiModels.Task k, ApiModels.Tile t)
    {
        if (k != null)
        {
            if (k.itemIds != null) for (Integer id : k.itemIds) if (id != null && id > 0) return id;
            if (k.skill != null)
            {
                Integer cape = SKILL.get(k.skill.toLowerCase(Locale.ROOT));
                if (cape != null) return cape;
            }
            String text = " " + ((k.description == null ? "" : k.description) + " " + (k.sourceKey == null ? "" : k.sourceKey.replace('_', ' ')))
                .toLowerCase(Locale.ROOT) + " ";
            for (Map.Entry<String, Integer> e : SKILL.entrySet()) if (containsWord(text, e.getKey())) return e.getValue();
            for (Map.Entry<String, Integer> e : TITLE.entrySet()) if (containsWord(text, e.getKey())) return e.getValue();
        }
        if (t == null) return null;
        // XP tasks say "Team gains 100,000 XP"; the skill is only in the tile's name ("100K Fishing XP")
        String title = " " + (t.title == null ? "" : t.title.toLowerCase(Locale.ROOT)) + " ";
        for (Map.Entry<String, Integer> e : SKILL.entrySet()) if (containsWord(title, e.getKey())) return e.getValue();
        return t.iconItemId != null ? t.iconItemId : null;
    }

    /** Last resort for a task with nothing of its own: the tile's own item, else an item picked from its title/emoji. */
    public static Integer taskFallback(ApiModels.Tile t)
    {
        return t == null ? null : t.iconItemId != null ? t.iconItemId : fallbackItem(t);
    }

    /** "cox" matches "CoX run" but not "coxswain"; multi-word keys match as a phrase. */
    private static boolean containsWord(String padded, String key)
    {
        int i = padded.indexOf(key);
        while (i >= 0)
        {
            boolean before = i == 0 || !Character.isLetterOrDigit(padded.charAt(i - 1));
            int end = i + key.length();
            boolean after = end >= padded.length() || !Character.isLetterOrDigit(padded.charAt(end));
            if (before && after) return true;
            i = padded.indexOf(key, i + 1);
        }
        return false;
    }
}

package com.forgebingo.core;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * Tile rules shared by the sidebar panel and the board overlay (owner request, 2026-11-07), matching the website:
 * hidden secret tiles, points per task, "needs changes" after a reviewer sends proof back, and "what's next".
 * Works with older servers too: fields they do not send fall back to what the board already had.
 */
public final class TileInfo
{
    public enum State { EMPTY, SECRET, DONE, NEEDS_CHANGES, WAITING, IN_PROGRESS, NOT_STARTED }

    private TileInfo()
    {
    }

    /** What a tile is called on screen: a hidden secret tile shows the name its organizer gave it, else "Secret tile". */
    public static String shownTitle(ApiModels.Tile t)
    {
        if (t == null) return "";
        if (isSecret(t) && !t.completed && (t.title == null || t.title.isEmpty() || "?".equals(t.title))) return "Secret tile";
        return t.title == null ? "" : t.title;
    }

    /** A hidden secret tile: the server sends "?" and no tasks (and, newer servers, secret=true). */
    public static boolean isSecret(ApiModels.Tile t)
    {
        if (t == null) return false;
        if (t.secret != null) return t.secret;
        return "?".equals(t.title) && (t.tasks == null || t.tasks.isEmpty());
    }

    /** Points the tile is worth: the sum of its task points (servers before task points: the tile's own points). */
    public static int worth(ApiModels.Tile t)
    {
        if (t == null) return 0;
        int sum = 0;
        boolean any = false;
        if (t.tasks != null)
        {
            for (ApiModels.Task k : t.tasks)
            {
                if (k.points != null)
                {
                    sum += Math.max(0, k.points);
                    any = true;
                }
            }
        }
        if (!any) return t.points;
        // "any one task finishes it": the best task counts
        if ("any".equals(t.completionMode))
        {
            int best = 0;
            for (ApiModels.Task k : t.tasks) if (k.points != null) best = Math.max(best, k.points);
            return best;
        }
        return sum;
    }

    /** The newest proof on one of its unfinished tasks was sent back. Returns the reason, or null. */
    public static String needsChangesReason(ApiModels.Tile t)
    {
        if (t == null || t.completed || t.tasks == null) return null;
        for (ApiModels.Task k : t.tasks)
        {
            if (!k.completed && k.pendingQty == 0 && k.rejectedReason != null && !k.rejectedReason.isEmpty()) return k.rejectedReason;
        }
        return null;
    }

    public static boolean waiting(ApiModels.Tile t)
    {
        if (t == null || t.tasks == null) return false;
        for (ApiModels.Task k : t.tasks) if (k.pendingQty > 0) return true;
        return false;
    }

    /** How far along the tile is, 0..1 (approved quantities; "any" tiles take their best task). */
    public static double progress(ApiModels.Tile t)
    {
        if (t == null) return 0;
        if (t.completed) return 1;
        if (t.tasks == null || t.tasks.isEmpty()) return 0;
        double total = 0;
        double best = 0;
        for (ApiModels.Task k : t.tasks)
        {
            double p = k.completed ? 1 : k.requiredQty <= 0 ? 0 : Math.min(1, (double) k.approvedQty / k.requiredQty);
            total += p;
            best = Math.max(best, p);
        }
        return "any".equals(t.completionMode) ? best : total / t.tasks.size();
    }

    public static State state(ApiModels.Tile t)
    {
        if (t == null) return State.EMPTY;
        if (isSecret(t)) return t.completed ? State.DONE : State.SECRET;
        if (t.completed) return State.DONE;
        if (needsChangesReason(t) != null) return State.NEEDS_CHANGES;
        if (waiting(t)) return State.WAITING;
        return progress(t) > 0 ? State.IN_PROGRESS : State.NOT_STARTED;
    }

    /** The open tiles closest to done (secret and empty tiles left out), most progress first, then most points. */
    public static List<ApiModels.Tile> nextUp(List<ApiModels.Tile> tiles, int n)
    {
        List<ApiModels.Tile> open = new ArrayList<>();
        if (tiles == null) return open;
        for (ApiModels.Tile t : tiles)
        {
            if (t == null || t.completed || isSecret(t) || t.tasks == null || t.tasks.isEmpty()) continue;
            open.add(t);
        }
        open.sort(Comparator.comparingDouble((ApiModels.Tile t) -> -progress(t)).thenComparingInt(t -> -worth(t)));
        return open.subList(0, Math.min(n, open.size()));
    }

    /** "3/5" style progress for the tile's least-finished task, or "" when there is nothing to count. */
    public static String countText(ApiModels.Tile t)
    {
        if (t == null || t.tasks == null) return "";
        for (ApiModels.Task k : t.tasks)
        {
            if (!k.completed && k.requiredQty > 1) return Math.min(k.approvedQty, k.requiredQty) + "/" + k.requiredQty;
        }
        int done = 0;
        for (ApiModels.Task k : t.tasks) if (k.completed) done++;
        return t.tasks.size() > 1 ? done + "/" + t.tasks.size() + " tasks" : "";
    }
}

package com.forgebingo.core;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/**
 * Whole-window proof screenshots (opt-in "Include sidebar in screenshots", owner request 2026-11-07).
 * Swing can paint the RuneLite window (sidebar, plugin panel, title bar), but the game area is drawn by the GPU and
 * comes out blank, so the game frame from the draw manager is laid over it at the canvas position.
 */
public final class WindowShot
{
    /** Larger windows fall back to the game screen only (keeps uploads under the size cap). */
    public static final int MAX_SIDE = 4096;

    private WindowShot()
    {
    }

    /**
     * Lays {@code game} over {@code window} at the canvas rectangle. Returns {@code game} unchanged when the window
     * capture is missing, too big or the canvas does not fit inside it.
     */
    public static BufferedImage compose(BufferedImage window, BufferedImage game, int canvasX, int canvasY, int canvasW, int canvasH)
    {
        if (window == null || game == null)
        {
            return game;
        }
        int w = window.getWidth();
        int h = window.getHeight();
        if (w <= 0 || h <= 0 || w > MAX_SIDE || h > MAX_SIDE || canvasW <= 0 || canvasH <= 0
            || canvasX < 0 || canvasY < 0 || canvasX + canvasW > w || canvasY + canvasH > h)
        {
            return game;
        }
        BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = out.createGraphics();
        try
        {
            g.drawImage(window, 0, 0, null);
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            g.drawImage(game, canvasX, canvasY, canvasW, canvasH, null);
        }
        finally
        {
            g.dispose();
        }
        return out;
    }
}

