        w.onInventoryAdded(OATHPLATE_HELM, 1, 10);
        assertEquals(1, w.flush(11, false).size());
        w.onInventoryAdded(OATHPLATE_HELM, 1, 50);
        assertEquals(1, w.flush(51, false).size());
    }

    @Test
    public void bankWithdrawEquipmentAndTradeAreMoves()
    {
