package com.forgebingo.core;

import static org.junit.Assert.*;

import java.util.Random;
import org.junit.Test;

public class BackoffAndErrorTest
{
    @Test
    public void exponentialWithoutJitter()
    {
        assertEquals(5_000, Backoff.delayMillis(1, 0, null));
        assertEquals(10_000, Backoff.delayMillis(2, 0, null));
        assertEquals(20_000, Backoff.delayMillis(3, 0, null));
        assertEquals(Backoff.MAX_MILLIS, Backoff.delayMillis(30, 0, null));
    }

    @Test
    public void jitterStaysWithinTwentyPercent()
    {
        Random r = new Random(1);
        for (int i = 0; i < 200; i++)
        {
            long d = Backoff.delayMillis(3, 0, r);
            assertTrue(d >= 16_000 && d <= 24_000);
        }
    }

    @Test
    public void retryAfterWins()
    {
        assertEquals(60_000, Backoff.delayMillis(1, 60_000, null));
        assertEquals(20_000, Backoff.delayMillis(3, 1_000, null));
        assertEquals(60_000, Backoff.parseRetryAfterMillis(" 60 "));
        assertEquals(0, Backoff.parseRetryAfterMillis("Wed, 21 Oct 2026 07:28:00 GMT"));
        assertEquals(0, Backoff.parseRetryAfterMillis(null));
    }

    @Test
    public void classification()
    {
        assertEquals(ErrorClass.SUCCESS, ErrorClass.of(200));
        assertEquals(ErrorClass.SUCCESS, ErrorClass.of(201));
        // transient: network, 429 (Retry-After), 5xx
        assertEquals(ErrorClass.TRANSIENT, ErrorClass.of(0));
        assertEquals(ErrorClass.TRANSIENT, ErrorClass.of(429, "rate_limited"));
        assertEquals(ErrorClass.TRANSIENT, ErrorClass.of(500, "internal_error"));
        assertEquals(ErrorClass.TRANSIENT, ErrorClass.of(503));
        // auth: only 401 invalid_api_key pauses the queue
        assertEquals(ErrorClass.AUTH, ErrorClass.of(401, "invalid_api_key"));
        // permanent: every documented 400 code, 403 not_a_member, 404, 413, 415
        for (String code : new String[] {"invalid_payload", "invalid_items", "invalid_rsn", "invalid_account_hash",
            "unsupported_source_type", "occurred_at_out_of_range", "invalid_json"})
        {
            assertEquals(code, ErrorClass.PERMANENT, ErrorClass.of(400, code));
        }
        assertEquals(ErrorClass.PERMANENT, ErrorClass.of(403, "not_a_member"));
        assertEquals(ErrorClass.PERMANENT, ErrorClass.of(404, "not_found"));
        assertEquals(ErrorClass.PERMANENT, ErrorClass.of(413, "payload_too_large"));
        assertEquals(ErrorClass.PERMANENT, ErrorClass.of(415, "unsupported_media_type"));
        // 409 event_id_conflict: regenerate the id
        assertEquals(ErrorClass.CONFLICT, ErrorClass.of(409, "event_id_conflict"));
        assertEquals(ErrorClass.PERMANENT, ErrorClass.of(409, "something_else"));
    }

    @Test
    public void iconPathGuard()
    {
        assertTrue(IconRef.isProxyPath("/v1/icons/items/4151.png"));
        assertTrue(IconRef.isProxyPath("/v1/icons/tiles/00000000-0000-4000-b000-000000000001"));
        assertFalse(IconRef.isProxyPath("/v1/icons/items/4151.png?x=1"));
        assertFalse(IconRef.isProxyPath("/v1/icons/items/abc.png"));
        assertFalse(IconRef.isProxyPath("/v1/icons/item/4151.png"));
        assertFalse(IconRef.isProxyPath("https://evil.example/x.png"));
        assertFalse(IconRef.isProxyPath("/v1/icons/../me"));
        assertFalse(IconRef.isProxyPath("//evil.example/v1/icons/x"));
        assertFalse(IconRef.isProxyPath("/v1/me"));
        assertFalse(IconRef.isProxyPath(null));
    }

    @Test
    public void baseUrlValidation()
    {
        assertNotNull(ApiClient.parseBaseUrl("https://api.example.com/plugin-api"));
        assertNotNull(ApiClient.parseBaseUrl("http://localhost:54321/functions/v1/plugin-api"));
        assertNull(ApiClient.parseBaseUrl("http://example.com/"));
        assertNull(ApiClient.parseBaseUrl("ftp://example.com/"));
        assertNull(ApiClient.parseBaseUrl("not a url"));
        assertTrue(ApiClient.isPlaceholder("https://YOUR-PROJECT-REF.supabase.co/functions/v1/plugin-api"));
        assertFalse(ApiClient.isPlaceholder("https://abcdefgh.supabase.co/functions/v1/plugin-api"));
        assertNull(ApiClient.parseBaseUrl(null));
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.awt.Rectangle;
import org.junit.Test;

public class BoardLayoutTest
{
    private static void assertInside(Rectangle outer, Rectangle inner)
    {
        assertTrue(inner + " inside " + outer, outer.contains(inner));
    }

    @Test
    public void tenByTenFitsFixedModeWithMinimumCells()
    {
        BoardLayout l = BoardLayout.compute(765, 503, 10);
        assertTrue(l.cell >= BoardLayout.MIN_CELL);
        Rectangle view = new Rectangle(0, 0, 765, 503);
        assertInside(view, l.board());
        assertInside(l.board(), l.grid());
        assertInside(view, l.card());
        assertTrue(l.board().height <= 503 * BoardLayout.MAX_FRACTION + 1);
    }

    @Test
    public void boardIsCentredAndCapped()
    {
        for (int n = 3; n <= 10; n++)
        {
            BoardLayout l = BoardLayout.compute(1920, 1080, n);
            Rectangle b = l.board();
            assertTrue(b.height <= 1080 * BoardLayout.MAX_FRACTION + 1);
            assertTrue(Math.abs((b.x + b.width / 2) - 960) <= 1);
            assertTrue(Math.abs((b.y + b.height / 2) - 540) <= 1);
            assertEquals(l.grid().width, l.grid().height);
            // last cell sits flush with the grid's bottom-right corner
            Rectangle last = l.cell(n - 1, n - 1);
            Rectangle g = l.grid();
            assertEquals(g.x + g.width, last.x + last.width);
            assertEquals(g.y + g.height, last.y + last.height);
            assertEquals(BoardLayout.GAP, l.gap);
        }
    }

    @Test
    public void tinyViewportStillFits()
    {
        BoardLayout l = BoardLayout.compute(200, 160, 10);
        Rectangle view = new Rectangle(0, 0, 200, 160);
        assertInside(view, l.board());
        assertInside(view, l.card());
        assertTrue(l.cell >= 2);
        BoardLayout z = BoardLayout.compute(0, 0, 10);
        assertTrue(z.cell >= 2);
    }

    @Test
    public void smallViewportGrowsCellsToMinimumWhenThereIsRoom()
    {
        // 80% of 420 leaves cells under 28, but the whole viewport fits 28px cells
        BoardLayout l = BoardLayout.compute(640, 420, 10);
        assertEquals(BoardLayout.MIN_CELL, l.cell);
        assertInside(new Rectangle(0, 0, 640, 420), l.board());
    }

    @Test
    public void cellAtHitsCellsAndMissesGaps()
    {
        BoardLayout l = BoardLayout.compute(1280, 900, 5);
        for (int r = 0; r < 5; r++)
        {
            for (int c = 0; c < 5; c++)
            {
                Rectangle cell = l.cell(r, c);
                assertEquals(r * 5 + c, l.cellAt(cell.x, cell.y));
                assertEquals(r * 5 + c, l.cellAt(cell.x + cell.width - 1, cell.y + cell.height - 1));
                assertEquals(r * 5 + c, l.cellAt((int) cell.getCenterX(), (int) cell.getCenterY()));
            }
        }
        Rectangle first = l.cell(0, 0);
        assertEquals(-1, l.cellAt(first.x + first.width, first.y)); // the gap after the first cell
        assertEquals(-1, l.cellAt(first.x - 1, first.y));
        Rectangle g = l.grid();
        assertEquals(-1, l.cellAt(g.x + g.width, g.y));
        assertEquals(-1, l.cellAt(g.x, g.y + g.height));
    }

    @Test
    public void insideBoardCloseButtonAndCard()
    {
        BoardLayout l = BoardLayout.compute(1280, 900, 4);
        Rectangle b = l.board();
        assertTrue(l.insideBoard(b.x, b.y));
        assertTrue(l.insideBoard(b.x + b.width - 1, b.y + b.height - 1));
        assertFalse(l.insideBoard(b.x - 1, b.y));
        assertFalse(l.insideBoard(b.x + b.width, b.y));
        assertFalse(l.insideBoard(5, 5));
        Rectangle close = l.closeButton();
        assertInside(b, close);
        assertTrue(l.onCloseButton((int) close.getCenterX(), (int) close.getCenterY()));
        assertEquals(-1, l.cellAt((int) close.getCenterX(), (int) close.getCenterY()));
        Rectangle card = l.card();
        assertTrue(l.insideCard((int) card.getCenterX(), (int) card.getCenterY()));
        assertFalse(l.insideCard(card.x - 1, card.y));
        // card is about 60% of the board's width and centred on it
        assertTrue(Math.abs(card.width - b.width * 0.6) <= 1);
        assertTrue(Math.abs(card.getCenterX() - b.getCenterX()) <= 1);
    }

    @Test
    public void cardHasAReadableMinimumOnSmallBoards()
    {
        BoardLayout l = BoardLayout.compute(765, 503, 10);
        assertTrue(l.card().width >= 260);
        assertTrue(l.card().height >= 220);
    }

    @Test
    public void messageBoxIsCentred()
    {
        Rectangle m = BoardLayout.message(765, 503);
        assertInside(new Rectangle(0, 0, 765, 503), m);
        assertTrue(Math.abs(m.getCenterX() - 382.5) <= 1);
    }

    @Test
    public void easeOutIsClampedAndMonotonic()
    {
        assertEquals(0.0, BoardLayout.easeOut(-1), 1e-9);
        assertEquals(0.0, BoardLayout.easeOut(0), 1e-9);
        assertEquals(1.0, BoardLayout.easeOut(1), 1e-9);
        assertEquals(1.0, BoardLayout.easeOut(3), 1e-9);
        assertTrue(BoardLayout.easeOut(0.5) > 0.5); // ease-out is ahead of linear
        double prev = 0;
        for (int i = 1; i <= 20; i++)
        {
            double v = BoardLayout.easeOut(i / 20.0);
            assertTrue(v >= prev);
            prev = v;
        }
    }
}

package com.forgebingo.core;

import static org.junit.Assert.*;

import org.junit.Test;

public class ChatParsersTest
{
    @Test
    public void combatTask()
    {
        ChatParsers.CombatTask t = ChatParsers.combatTask(
            "Congratulations, you've completed a hard combat task: <col=06600c>Noxious Foe</col> (3 points).").get();
        assertEquals("hard", t.tier);
        assertEquals("Noxious Foe", t.name);
        assertEquals("Fragment of Seren Speedrunner",
            ChatParsers.combatTask("Congratulations, you've completed an elite combat task: Fragment of Seren Speedrunner.").get().name);
        assertFalse(ChatParsers.combatTask("You've completed a quest: Dragon Slayer I").isPresent());
    }

    @Test
    public void collectionLogSlot()
    {
        assertEquals("Abyssal whip", ChatParsers.collectionLogItem("New item added to your collection log: Abyssal whip").get());
        assertEquals("Tumeken's shadow (uncharged)",
            ChatParsers.collectionLogItem("<col=ef1020>New item added to your collection log: Tumeken's shadow (uncharged)</col>").get());
    }

    @Test
    public void collectionLogRejectsOther()
    {
        assertFalse(ChatParsers.collectionLogItem("You added an item to your bank").isPresent());
        assertFalse(ChatParsers.collectionLogItem("New item added to your collection log:").isPresent());
        assertFalse(ChatParsers.collectionLogItem(null).isPresent());
        // a player cannot spoof via a prefix
        assertFalse(ChatParsers.collectionLogItem("Zezima: New item added to your collection log: Dragon pickaxe").isPresent());
    }

    @Test
    public void petMessages()
    {
        assertEquals(ChatParsers.Pet.FOLLOWING, ChatParsers.pet("You have a funny feeling like you're being followed.").get());
        assertEquals(ChatParsers.Pet.FOLLOWING, ChatParsers.pet("You have a funny feeling like you’re being followed.").get());
        assertEquals(ChatParsers.Pet.BACKPACK, ChatParsers.pet("You feel something weird sneaking into your backpack.").get());
        assertEquals(ChatParsers.Pet.DUPLICATE,
            ChatParsers.pet("You have a funny feeling like you would have been followed...").get());
        assertEquals(ChatParsers.Pet.DUPLICATE,
            ChatParsers.pet("You have a funny feeling like you would have been followed.").get());
        assertEquals(ChatParsers.Pet.FOLLOWING,
            ChatParsers.pet("<col=ef1020>You have a funny feeling like you're being followed.</col>").get());
        assertTrue(ChatParsers.Pet.BACKPACK.isNew());
        assertFalse(ChatParsers.Pet.DUPLICATE.isNew());
        assertFalse(ChatParsers.pet("You have a funny feeling about this.").isPresent());
        assertFalse(ChatParsers.pet("Zezima: You have a funny feeling like you're being followed.").isPresent());
    }

    @Test
    public void killCountVariants()
    {
        ChatParsers.Kc k = ChatParsers.killCount("Your Zulrah kill count is: <col=ff0000>1234</col>.").get();
        assertEquals("Zulrah", k.boss);
        assertEquals(1234, k.count);

        k = ChatParsers.killCount("Your Vorkath kill count is: 5.").get();
        assertEquals("Vorkath", k.boss);
        assertEquals(5, k.count);

        k = ChatParsers.killCount("Your completed Theatre of Blood count is: 12.").get();
        assertEquals("Theatre of Blood", k.boss);
        assertEquals(12, k.count);

        k = ChatParsers.killCount("Your Barrows chest count is: 300.").get();
        assertEquals("Barrows", k.boss);

        k = ChatParsers.killCount("Your subdued Wintertodt count is: 40.").get();
        assertEquals("Wintertodt", k.boss);

        k = ChatParsers.killCount("Your Chambers of Xeric count is: 7.").get();
        assertEquals("Chambers of Xeric", k.boss);
        assertEquals(7, k.count);

        k = ChatParsers.killCount("Your Hallowed Sepulchre lap count is: 9.").get();
        assertEquals("Hallowed Sepulchre", k.boss);
    }

    @Test
    public void killCountThousandsAndCompletionFor()
    {
        ChatParsers.Kc k = ChatParsers.killCount("Your Zulrah kill count is: <col=ff0000>1,234</col>.").get();
        assertEquals("Zulrah", k.boss);
        assertEquals(1234, k.count);
        k = ChatParsers.killCount("Your completion count for Tombs of Amascut: Expert Mode is: 2,001.").get();
        assertEquals("Tombs of Amascut: Expert Mode", k.boss);
        assertEquals(2001, k.count);
        k = ChatParsers.killCount("Your Lunar Chest count is: 3.").get();
        assertEquals("Lunar Chest", k.boss);
        assertFalse(ChatParsers.killCount("Your Zulrah kill count is: 9,999,999,999.").isPresent());
    }

    @Test
    public void clueCompletions()
    {
        ChatParsers.Clue c = ChatParsers.clueCompletion("<col=ef1020>You have completed 12 hard Treasure Trails.</col>").get();
        assertEquals("hard", c.tier);
        assertEquals(12, c.count);
        assertEquals("Clue scroll (hard)", c.sourceName());
        c = ChatParsers.clueCompletion("You have completed 1 beginner Treasure Trail.").get();
        assertEquals("beginner", c.tier);
        assertEquals(1, c.count);
        c = ChatParsers.clueCompletion("You have completed 1,502 Elite Treasure Trails.").get();
        assertEquals("elite", c.tier);
        assertEquals(1502, c.count);
        for (String t : new String[]{"easy", "medium", "master"})
        {
            assertEquals(t, ChatParsers.clueCompletion("You have completed 3 " + t + " Treasure Trails.").get().tier);
        }
        assertFalse(ChatParsers.clueCompletion("You have completed 3 shiny Treasure Trails.").isPresent());
        assertFalse(ChatParsers.clueCompletion("Bob: You have completed 3 hard Treasure Trails.").isPresent());
        assertFalse(ChatParsers.clueCompletion("You have completed the Treasure Trail.").isPresent());
    }

    @Test
    public void petBroadcasts()
    {
        ChatParsers.PetBroadcast b = ChatParsers.petBroadcast(
            "<img=2>Zezima has a funny feeling like he's being followed: Vorki at 1,234 killcount.").get();
        assertEquals("Zezima", b.player);
        assertEquals("Vorki", b.petName);
        assertFalse(b.duplicate);
        b = ChatParsers.petBroadcast("Iron Man 1 feels something weird sneaking into her backpack: Heron at 99 Fishing.").get();
        assertEquals("Iron Man 1", b.player);
        assertEquals("Heron", b.petName);
        assertFalse(b.duplicate);
        b = ChatParsers.petBroadcast("Zezima has a funny feeling like they would have been followed: Lil' zik at 50 killcount.").get();
        assertEquals("Lil' zik", b.petName);
        assertTrue(b.duplicate);
        b = ChatParsers.petBroadcast("Zezima has a funny feeling like they're being followed: Pet snakeling.").get();
        assertEquals("Pet snakeling", b.petName);
        assertFalse(ChatParsers.petBroadcast("Zezima received a drop: Vorki").isPresent());
    }

    @Test
    public void killCountRejects()
    {
        assertFalse(ChatParsers.killCount("Your Zulrah kill count is: lots.").isPresent());
        assertFalse(ChatParsers.killCount("Your Zulrah kill count is: 99999999999999.").isPresent());
        assertFalse(ChatParsers.killCount("Bob: Your Zulrah kill count is: 5.").isPresent());
        assertFalse(ChatParsers.killCount("Fight duration: 1:23. Personal best: 1:20").isPresent());
    }

    @Test
    public void stripTags()
    {
        assertEquals("a b", ChatParsers.stripTags("<col=ff0000>a</col> b"));
        assertEquals("", ChatParsers.stripTags(null));
    }

    @Test
    public void sourceClassifier()
    {
        assertEquals(GameEvent.CLUE, SourceClassifier.forEventLoot("Reward Casket (elite)"));
        assertEquals(GameEvent.RAID_CHEST, SourceClassifier.forEventLoot("Chambers of Xeric"));
        assertEquals(GameEvent.RAID_CHEST, SourceClassifier.forEventLoot("Barrows"));
        assertEquals(GameEvent.RAID_CHEST, SourceClassifier.forEventLoot(null));
        assertEquals(GameEvent.CLUE, SourceClassifier.forEventLoot("Clue Scroll (Master)"));
        assertEquals("master", SourceClassifier.clueTier("Clue Scroll (Master)"));
    }
}

package com.forgebingo.core;

import static org.junit.Assert.*;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.List;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/** POST /v1/hello, RSN verification wording, revoked keys (docs/API.md section 8). */
public class ConnectionStatusTest
{
    private final Gson gson = new Gson();
    private MockWebServer server;
    private ApiClient client;

    @Before
    public void start() throws IOException
    {
        server = new MockWebServer();
        server.start();
        String base = server.url("/plugin-api").toString();
        client = new ApiClient(new OkHttpClient(), gson, () -> base, () -> "fb2_test_key", "2.0.0-test");
    }

    @After
    public void stop() throws IOException
    {
        server.shutdown();
    }

    private static ApiModels.Membership m(String status, String joined, String plugin)
    {
        ApiModels.Membership m = new ApiModels.Membership();
        m.eventName = "Forge Bingo";
        m.teamName = "Wolves";
        m.status = status;
        m.verified = "verified".equals(status);
        m.joinedRsn = joined;
        m.pluginRsn = plugin;
        return m;
    }

    @Test
    public void helloPostsRsnAndAccountHashOnly() throws Exception
    {
        server.enqueue(new MockResponse().setBody("{\"displayName\":\"Gus\",\"rsn\":\"Gus\",\"keyScope\":\"event\",\"memberships\":["
            + "{\"eventId\":\"e1\",\"eventName\":\"Forge\",\"teamId\":\"t1\",\"teamName\":\"Wolves\",\"joinedRsn\":\"Gus\","
            + "\"pluginRsn\":\"Gus\",\"status\":\"verified\",\"verified\":true}]}"));
        ApiResult<ApiModels.HelloResponse> r = client.hello("Gus B", "-42");
        assertTrue(r.describe(), r.ok());
        assertEquals("event", r.body.keyScope);
        assertTrue(r.body.memberships.get(0).verified);
        RecordedRequest req = server.takeRequest();
        assertEquals("POST", req.getMethod());
        assertEquals("/plugin-api/v1/hello", req.getPath());
        assertEquals("fb2_test_key", req.getHeader("X-API-Key"));
        assertEquals("{\"rsn\":\"Gus B\",\"accountHash\":\"-42\"}", req.getBody().readUtf8());
    }

    @Test
    public void helloIsNotSentWhenNotLoggedIn()
    {
        assertEquals(400, client.hello(null, "1").status);
        assertEquals(400, client.hello("bad!name", "1").status);
        assertEquals(400, client.hello("Gus", "abc").status);
        assertEquals(0, server.getRequestCount());
    }

    @Test
    public void helloResponseIsSanitised() throws Exception
    {
        StringBuilder many = new StringBuilder("{\"memberships\":[");
        for (int i = 0; i < 30; i++)
        {
            many.append(i == 0 ? "" : ",").append("{\"status\":\"verified\",\"eventName\":\"E\\u0007vil\"}");
        }
        server.enqueue(new MockResponse().setBody(many.append("]}").toString()));
        ApiModels.HelloResponse r = client.hello("Gus", "1").body;
        assertEquals(20, r.memberships.size());
        assertEquals("E vil", r.memberships.get(0).eventName);
    }

    @Test
    public void revokedKeyMessageSaysWhereToGetANewOne() throws Exception
    {
        server.enqueue(new MockResponse().setResponseCode(401)
            .setBody("{\"error\":\"api_key_revoked\",\"message\":\"This key was revoked or replaced.\"}"));
        ApiResult<ApiModels.Me> r = client.me();
        assertEquals(ErrorClass.AUTH, r.errorClass());
        assertEquals("api_key_revoked", r.errorCode);
        String msg = ConnectionStatus.authMessage(r.errorCode);
        assertTrue(msg, msg.contains("stopped working"));
        assertTrue(msg, msg.contains("Connect RuneLite"));
        assertTrue(ConnectionStatus.authMessage("invalid_api_key").contains("wasn't recognised"));
    }

    @Test
    public void verifiedLineShowsRsnEventAndTeam()
    {
        ConnectionStatus.Line l = ConnectionStatus.line(m("verified", "Gus", "Gus"));
        assertEquals(ConnectionStatus.Level.OK, l.level);
        assertEquals("Tracking drops as Gus for Wolves (Forge Bingo).", l.text);
    }

    @Test
    public void verifiedBoardsShareOneCard()
    {
        ApiModels.HelloResponse r = new ApiModels.HelloResponse();
        r.memberships = new java.util.ArrayList<>(java.util.Arrays.asList(m("verified", "Gus", "Gus"), m("verified", "Gus", "Gus"),
            m("rsn_mismatch", "Zezima", "Gus")));
