package com.forgebingo.core;

import static org.junit.Assert.*;

import java.util.Arrays;
import java.util.Collections;
import java.util.Optional;
import org.junit.Test;

public class PetDetectorTest
{
    private final PetDetector d = new PetDetector();

    @Test
    public void followerIdentifiesNewPet()
    {
        assertFalse(d.onPetMessage(ChatParsers.Pet.FOLLOWING, 100).isPresent());
        assertTrue(d.wantsFollower());
        assertFalse(d.wantsInventory());
        assertFalse(d.onFollower(2215, 100).isPresent()); // not a pet follower
        PetDetector.Drop drop = d.onFollower(6635, 101).get();
        assertEquals("Baby mole", drop.pet.name);
        assertFalse(drop.duplicate);
        assertEquals("follower", drop.via);
        assertFalse(d.pending());
        assertFalse(d.onFollower(6635, 102).isPresent()); // reported once
    }

    @Test
    public void followerIgnoredForBackpackCase()
    {
        // a pet that was already following must not be mistaken for the one that went into the backpack
        d.onPetMessage(ChatParsers.Pet.BACKPACK, 50);
        assertFalse(d.onFollower(8029, 50).isPresent());
        assertFalse(d.onInventoryAdded(Collections.singletonList(995), 51).isPresent());
        PetDetector.Drop drop = d.onInventoryAdded(Arrays.asList(995, 13320), 51).get();
        assertEquals("Heron", drop.pet.name);
        assertEquals("inventory", drop.via);
    }

    @Test
    public void inventoryIgnoredWithoutBackpackLine()
    {
        assertFalse(d.onInventoryAdded(Collections.singletonList(12646), 5).isPresent());
        d.onPetMessage(ChatParsers.Pet.FOLLOWING, 6);
        assertFalse(d.onInventoryAdded(Collections.singletonList(12646), 6).isPresent());
    }

    @Test
    public void collectionLogAfterOrBeforeTheLine()
    {
        d.onPetMessage(ChatParsers.Pet.FOLLOWING, 10);
        assertEquals("Olmlet", d.onCollectionLog("Olmlet", 10).get().pet.name);
        assertFalse(d.onFollower(7520, 11).isPresent()); // already reported

        PetDetector d2 = new PetDetector();
        assertFalse(d2.onCollectionLog("Tiny tempor", 20).isPresent());
        PetDetector.Drop drop = d2.onPetMessage(ChatParsers.Pet.BACKPACK, 21).get();
        assertEquals("Tiny tempor", drop.pet.name);
        assertEquals("collection_log", drop.via);
    }

    @Test
    public void collectionLogOfOrdinaryItemsIsIgnored()
    {
        d.onPetMessage(ChatParsers.Pet.FOLLOWING, 10);
        assertFalse(d.onCollectionLog("Abyssal whip", 10).isPresent());
        assertTrue(d.pending());
    }

    @Test
    public void staleEarlySignalIsNotPaired()
    {
        d.onCollectionLog("Vorki", 0);
        d.onTick(PetDetector.WINDOW_TICKS + 1);
        assertFalse(d.onPetMessage(ChatParsers.Pet.FOLLOWING, 500).isPresent());
    }

    @Test
    public void duplicateNamedByBroadcast()
    {
        d.onPetMessage(ChatParsers.Pet.DUPLICATE, 30);
        assertFalse(d.wantsFollower());
        PetDetector.Drop drop = d.onBroadcast("Vorki", true, 31).get();
        assertEquals("Vorki", drop.pet.name);
        assertTrue(drop.duplicate);
        assertEquals("broadcast", drop.via);
    }

    @Test
    public void duplicateAttributedToTheBossJustKilled()
    {
        d.onSource("Vorkath", 39);
        d.onPetMessage(ChatParsers.Pet.DUPLICATE, 40);
        assertFalse(d.onTick(40 + PetDetector.WINDOW_TICKS).isPresent());
        PetDetector.Drop drop = d.onTick(41 + PetDetector.WINDOW_TICKS).get();
        assertEquals("Vorki", drop.pet.name);
        assertTrue(drop.duplicate);
        assertEquals("source", drop.via);
    }

    @Test
    public void unidentifiedWhenNothingNamesThePet()
    {
        d.onSource("Goblin", 40);
        d.onPetMessage(ChatParsers.Pet.DUPLICATE, 40);
        Optional<PetDetector.Drop> drop = d.onTick(100);
        assertTrue(drop.isPresent());
        assertFalse(drop.get().identified());
        assertFalse(d.pending());
        assertFalse(d.onTick(101).isPresent());
    }

    @Test
    public void staleSourceIsNotUsed()
    {
        d.onSource("Vorkath", 0);
        d.onPetMessage(ChatParsers.Pet.DUPLICATE, 1000);
        assertFalse(d.onTick(1100).get().identified());
    }

    @Test
    public void newPetWithoutAnySignalIsReportedUnidentified()
    {
        d.onPetMessage(ChatParsers.Pet.FOLLOWING, 5);
        PetDetector.Drop drop = d.onTick(50).get();
        assertFalse(drop.identified());
        assertFalse(drop.duplicate);
    }

    @Test
    public void resetClearsState()
    {
        d.onPetMessage(ChatParsers.Pet.FOLLOWING, 1);
        d.reset();
        assertFalse(d.pending());
        assertFalse(d.onFollower(6635, 2).isPresent());
    }
}

package com.forgebingo.core;

import static org.junit.Assert.*;

import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

public class PetTableTest
{
    @Test
    public void wellKnownPets()
    {
        PetTable.Pet mole = PetTable.byName("Baby mole");
        assertNotNull(mole);
        assertEquals(12646, mole.primaryItemId());
        assertSame(mole, PetTable.byItemId(12646));
        assertSame(mole, PetTable.byFollowerNpcId(6635));
        assertSame(mole, PetTable.bySource("Giant Mole").get(0));

        assertEquals(21992, PetTable.byName("vorki").primaryItemId());
        assertSame(PetTable.byName("Vorki"), PetTable.byFollowerNpcId(8029));
        assertEquals(20851, PetTable.byName("Olmlet").primaryItemId());
        assertEquals(20693, PetTable.byName("Phoenix").primaryItemId());
        assertEquals(12921, PetTable.byName("Pet snakeling").primaryItemId());
        assertEquals(12650, PetTable.byName("Pet general graardor").primaryItemId());
        assertSame(PetTable.byName("Pet general graardor"), PetTable.byFollowerNpcId(6632));
        // typographic apostrophe and odd casing from chat
        assertEquals(22473, PetTable.byName("Lil’ Zik").primaryItemId());
        assertEquals(13179, PetTable.byName("VET'ION JR.").primaryItemId());
    }

    @Test
    public void variantsMapToTheirPet()
    {
        PetTable.Pet hydra = PetTable.byName("Ikkle hydra");
        for (int id : new int[]{22746, 22748, 22750, 22752})
        {
            assertSame(hydra, PetTable.byItemId(id));
        }
        assertSame(PetTable.byName("Noon"), PetTable.byItemId(21750)); // Midnight
        assertSame(PetTable.byName("Youngllef"), PetTable.byItemId(23759)); // Corrupted youngllef
    }

    @Test
    public void tableIsConsistent()
    {
        assertTrue(PetTable.all().size() >= 60);
        Set<String> names = new HashSet<>();
        for (PetTable.Pet p : PetTable.all())
        {
            assertTrue(p.name, names.add(ItemNames.normalize(p.name)));
            assertTrue(p.name, p.itemIds.length > 0);
            assertTrue(p.name, p.followerNpcIds.length > 0);
            for (int id : p.itemIds) assertSame(p.name, p, PetTable.byItemId(id));
            for (int id : p.followerNpcIds) assertSame(p.name, p, PetTable.byFollowerNpcId(id));
        }
    }

    @Test
    public void unknowns()
    {
        assertNull(PetTable.byName("Abyssal whip"));
        assertNull(PetTable.byName(null));
        assertNull(PetTable.byItemId(4151));
        assertNull(PetTable.byFollowerNpcId(2215)); // General Graardor himself, not his pet
        assertNull(PetTable.byFollowerNpcId(494)); // the Kraken boss
        assertTrue(PetTable.bySource("Goblin").isEmpty());
        assertTrue(PetTable.bySource(null).isEmpty());
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import org.junit.Test;

public class ScreenshotStampTest
{
    private static final ZonedDateTime T = ZonedDateTime.of(2026, 11, 6, 14, 5, 0, 0, ZoneOffset.ofHours(2));

    private static BufferedImage white(int w, int h)
    {
        BufferedImage b = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
        for (int y = 0; y < h; y++) for (int x = 0; x < w; x++) b.setRGB(x, y, Color.WHITE.getRGB());
        return b;
    }

    @Test
    public void stampsTopLeftAndKeepsSize()
    {
        BufferedImage src = white(765, 503);
        BufferedImage out = ScreenshotStamp.stamp(src, "Zulrah42", T);
        assertEquals(765, out.getWidth());
        assertEquals(503, out.getHeight());
        assertNotEquals(Color.WHITE.getRGB() & 0xffffff, out.getRGB(2, 2) & 0xffffff);
        assertEquals(Color.WHITE.getRGB() & 0xffffff, out.getRGB(700, 450) & 0xffffff);
        assertEquals(Color.WHITE.getRGB(), src.getRGB(2, 2));
    }

    /** Tile, player, code and time make a taller box than the time alone (four lines instead of one). */
    @Test
    public void proofStampHasTilePlayerCodeAndTime()
    {
        BufferedImage full = ScreenshotStamp.stamp(white(765, 503), "Zulrah42", T, "Goonferno", "Big bones x10");
        BufferedImage bare = ScreenshotStamp.stamp(white(765, 503), null, T, null, null);
        int fullBox = boxHeight(full), bareBox = boxHeight(bare);
        assertTrue("4-line box " + fullBox + " vs 1-line " + bareBox, fullBox > bareBox * 3);
    }

    private static int boxHeight(BufferedImage img)
    {
        int y = 0;
        while (y < img.getHeight() && (img.getRGB(1, y) & 0xffffff) != (Color.WHITE.getRGB() & 0xffffff)) y++;
        return y;
    }

    @Test
    public void stampsTimeWithoutKeyword()
    {
        BufferedImage out = ScreenshotStamp.stamp(white(400, 300), null, T);
        assertNotEquals(Color.WHITE.getRGB() & 0xffffff, out.getRGB(2, 2) & 0xffffff);
        assertTrue(ScreenshotStamp.timeText(T).startsWith("2026-11-06 14:05 UTC+02:00"));
    }
}

