package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public class TileIconsTest
{
    private static ApiModels.Tile tile(String title, String emoji)
    {
        ApiModels.Tile t = new ApiModels.Tile();
        t.title = title;
        t.iconEmoji = emoji;
        t.tasks = Collections.emptyList();
        return t;
    }

    @Test
    public void titlesPickTheRightItem()
    {
        assertEquals(Integer.valueOf(2722), TileIcons.fallbackItem(tile("Hard clue", null)));
        assertEquals(Integer.valueOf(19835), TileIcons.fallbackItem(tile("Master clue", null)));
        assertEquals(Integer.valueOf(20851), TileIcons.fallbackItem(tile("CoX run", null)));
        assertEquals(Integer.valueOf(22473), TileIcons.fallbackItem(tile("ToB run", null)));
        assertEquals(Integer.valueOf(1333), TileIcons.fallbackItem(tile("Combat level", null)));
        assertEquals(Integer.valueOf(11640), TileIcons.fallbackItem(tile("Solo 250K XP", null)));
        assertEquals(Integer.valueOf(21018), TileIcons.fallbackItem(tile("Grandmaster raider", null)));
        assertEquals(Integer.valueOf(6199), TileIcons.fallbackItem(tile("Free space", null)));
    }

    @Test
    public void wordsMustBeWholeWords()
    {
        // "toa" inside "toast" must not pick the ToA icon
        assertNull(TileIcons.fallbackItem(tile("Toast", null)));
    }

    @Test
    public void emojiThenTaskItems()
    {
        assertEquals(Integer.valueOf(4716), TileIcons.fallbackItem(tile("Brothers", "⚰️")));
        ApiModels.Tile t = tile("Something", null);
        ApiModels.Task k = new ApiModels.Task();
        k.itemIds = Arrays.asList(4151);
        t.tasks = Collections.singletonList(k);
        assertEquals(Integer.valueOf(4151), TileIcons.fallbackItem(t));
        assertNull(TileIcons.fallbackItem(tile("Team photo", "📸")));
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class TileInfoTest
{
    private static ApiModels.Task task(int need, int have, Integer points)
    {
        ApiModels.Task k = new ApiModels.Task();
        k.requiredQty = need;
        k.approvedQty = have;
        k.completed = have >= need;
        k.points = points;
        k.description = "task";
        return k;
    }

    private static ApiModels.Tile tile(String title, ApiModels.Task... tasks)
    {
        ApiModels.Tile t = new ApiModels.Tile();
        t.title = title;
        t.points = 1;
        t.tasks = new ArrayList<>(Arrays.asList(tasks));
        return t;
    }

    @Test
    public void secretTilesWithAndWithoutTheServerFlag()
    {
        assertTrue(TileInfo.isSecret(tile("?")));                // older server: "?" and no tasks
        ApiModels.Tile flagged = tile("?");
        flagged.secret = false;                                  // revealed tile literally named "?"
        assertFalse(TileInfo.isSecret(flagged));
        assertEquals(TileInfo.State.SECRET, TileInfo.state(tile("?")));
    }

    @Test
    public void hiddenTileShowsTheOrganizersNameOrSecretTile()
    {
        assertEquals("Secret tile", TileInfo.shownTitle(tile("?")));
        ApiModels.Tile named = tile("Mystery Wildy tile");
        named.secret = true;
        assertEquals("Mystery Wildy tile", TileInfo.shownTitle(named));
        assertEquals("Bandos hilt", TileInfo.shownTitle(tile("Bandos hilt", new ApiModels.Task())));
    }

    @Test
    public void worthAddsTaskPointsAndFallsBackToTilePoints()
    {
        assertEquals(3, TileInfo.worth(tile("Rings", task(1, 0, 1), task(1, 0, 1), task(1, 0, 1))));
        assertEquals(1, TileInfo.worth(tile("Old server", task(1, 0, null))));
        ApiModels.Tile any = tile("Any", task(1, 0, 2), task(1, 0, 5));
        any.completionMode = "any";
        assertEquals(5, TileInfo.worth(any));
    }

    @Test
    public void needsChangesOnlyWhileNothingIsWaiting()
    {
        ApiModels.Task k = task(1, 0, 1);
        k.rejectedReason = "Drop message not visible";
        ApiModels.Tile t = tile("Whip", k);
        assertEquals("Drop message not visible", TileInfo.needsChangesReason(t));
        assertEquals(TileInfo.State.NEEDS_CHANGES, TileInfo.state(t));
        k.pendingQty = 1;                                        // new proof sent: waiting again
        assertNull(TileInfo.needsChangesReason(t));
        assertEquals(TileInfo.State.WAITING, TileInfo.state(t));
    }

    @Test
    public void nextUpPrefersTheClosestTiles()
    {
        ApiModels.Tile far = tile("Far", task(10, 1, 1));
        ApiModels.Tile close = tile("Close", task(10, 8, 1));
        ApiModels.Tile done = tile("Done", task(1, 1, 1));
        done.completed = true;
        List<ApiModels.Tile> next = TileInfo.nextUp(Arrays.asList(far, close, done, tile("?")), 3);
        assertEquals(2, next.size());
        assertEquals("Close", next.get(0).title);
        assertEquals("8/10", TileInfo.countText(close));
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

import java.awt.image.BufferedImage;
import org.junit.Test;

public class WindowShotTest
{
    private static BufferedImage filled(int w, int h, int rgb)
    {
        BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < h; y++)
        {
            for (int x = 0; x < w; x++)
            {
                img.setRGB(x, y, rgb);
            }
        }
        return img;
    }

    @Test
    public void gameIsLaidOverTheWindowAtTheCanvas()
    {
        BufferedImage window = filled(300, 200, 0x112233); // sidebar colour
        BufferedImage game = filled(100, 100, 0xff0000);
        BufferedImage out = WindowShot.compose(window, game, 10, 20, 100, 100);
        assertEquals(300, out.getWidth());
        assertEquals(200, out.getHeight());
        assertEquals(0xff0000, out.getRGB(50, 50) & 0xffffff);   // game area
        assertEquals(0x112233, out.getRGB(250, 100) & 0xffffff); // sidebar kept
    }

    @Test
    public void fallsBackToTheGameScreen()
    {
        BufferedImage game = filled(100, 100, 0xff0000);
        assertSame(game, WindowShot.compose(null, game, 0, 0, 100, 100));
        assertSame(game, WindowShot.compose(filled(50, 50, 0), game, 0, 0, 100, 100)); // canvas does not fit
        assertSame(game, WindowShot.compose(filled(WindowShot.MAX_SIDE + 1, 10, 0), game, 0, 0, 5, 5)); // too big
    }
}
